// The page guide text in Hebrew (page -> { title, lead, blocks:[{h,p,ex,tip,demo}] }).
const HELP = {
  dash:{title:"על מסך הבית",lead:"מסך הבית הוא תמונת המצב של הכסף שלך להיום: כמה יש לך, מה נכנס ומה יצא החודש, ומה מגיע בהמשך. כל מה שכאן מתייחס ל**חודש הנוכחי**, אלא אם כתוב אחרת.",blocks:[
    {h:"בשביל מה יש מסך בית",p:["הבית הוא סיכום. כל קופסה היא גרסה קטנה של עמוד אחר, והקישור **הכול ←** בקופסה לוקח אותך לעמוד המלא.","קופסה מופיעה רק כשיש בה מה להראות. באפליקציה חדשה לגמרי תראה כרטיס קצר **עדיין אין כאן כלום** עם שני כפתורים: **חיבור חשבון** ו**הוספת תנועה**.","אם מצביעים (או לוחצים) על רוב המספרים, אפשר לראות איך הם חושבו."],ex:"עוד אין לך קופות? הקופסה **קופות** פשוט לא מוצגת."},
    {h:"מה נספר ומה לא",p:["**תשלומים קבועים קרובים** הם תחזית. הם לא נספרים כהוצאה או כהכנסה ולא משנים יתרות או סיכומים. רק תשלום שמגיע החודש ועדיין לא שולם יורד: ב**תזרים כספים** הוא חלק מ**חשבונות שעוד לשלם החודש**."]},
    {h:"התראות בראש העמוד",p:["אם משהו דורש ממך תשומת לב, עד שלוש התראות מופיעות בקופסה מעל הכול. לחץ **פתיחה** כדי להגיע למה שההתראה מדברת עליו.","**כל ההתראות (n) ←** פותח את עמוד ההתראות המלא."],demo:"alert",ex:"**הכנסה גדולה: משכורת** על סך ₪18,900. לוחצים **פתיחה** ורואים את התשלום הזה בפעילות."},
    {h:"ארבעת המספרים הגדולים",p:["**בחשבונות שלכם** הוא הכסף שיש לך עכשיו בבנק וב-Wise, ועוד כל חשבון שלך שבחרת לספור. כרטיסי אשראי לא נכללים. אם יש פנסיה, שורה קטנה מראה את הסכום **עם פנסיה**. שורה נוספת אומרת בערך לכמה זמן הכסף הזה יספיק לפי ההוצאות הרגילות.","**נכנס** הוא כל הכסף שנכנס החודש עד עכשיו, גם הפקדת מזומן וגם המשכורת. החזר כספי (כמו זיכוי בכרטיס אשראי) הוא לא כסף שנכנס, והוא לא מוריד את מה שיצא: מצביעים על **נכנס** כדי לראות אותו בשורה נפרדת. **יצא** הוא מה שיצא עד עכשיו. **נחסך החודש (נכנס פחות יצא)** הוא מה שנכנס פחות מה שיצא: מה שנשאר לך.","העברת כסף בין החשבונות שלך, ותשלום חשבון כרטיס מהבנק, לא נחשבים להכנסה או להוצאה."],demo:"kpis",ex:"יש לך ₪30,583 בחשבונות. החודש נכנסו ₪18,900 ויצאו ₪10,013, אז **נחסך החודש** הוא ₪8,887."},
    {h:"חשבונות וכרטיסי אשראי",p:["**חשבונות** מראה כל בנק, ארנק וחשבון שלך עם היתרה שלו. בארנק עם כמה מטבעות מופיע כל מטבע ומה שווי בשקלים. לחיצה על חשבון פותחת את העמוד שלו. לחשבונות שהוספת ידנית יש תווית קטנה **ידני**.","**כרטיסים · החודש מול חודש שעבר** מראה כמה הוצאת בכל כרטיס עד עכשיו החודש (**חיוב קרוב**: חשבון הכרטיס יגבה אותו מאוחר יותר), לצד החודש שעבר. בכרטיס של Wise כתוב **משולם מיד**. החץ הקטן אומר אם אתה מוציא יותר (למעלה) או פחות (למטה). הפס משווה בין החודש הזה לחודש שעבר: אדום כשהוצאת יותר, ירוק כשהוצאת פחות."],demo:"account",ex:"כרטיס **Max ·· 1234**: ₪3,200 עד עכשיו, חודש שעבר ₪2,900. תראה **▲ 10%**."},
    {h:"תזרים כספים",p:["זו תוכנית לכסף שיש לך עכשיו, להמשך החודש. העמודה הראשונה היא **בחשבונות שלכם**: אותו מספר כמו בכרטיס למעלה. כל עמודה אחריה מורידה חלק: קניות בכרטיס שעוד לא שולמו, חשבונות שעוד לשלם החודש, מה ש**נשאר בתקציבים** החודש (מהגדול לקטן), ואז מה ש**בצד**: כסף בקופות וכרית הביטחון.","אחרי **קניות בכרטיס שעוד לא שולמו** ו**חשבונות שעוד לשלם החודש** (חשבונות שעוד לא שולמו החודש ותשלומים שכבר רשומים ליום מאוחר יותר) מופיע **הכסף שלכם אחרי התשלומים הידועים**: מה שנשאר אחרי שהסכומים שכבר ידועים ישולמו.","מעל כל עמודה מופיע הסכום שלה. בבלוק מתחת לעמודה מופיע **מה שנשאר** מהכסף אחרי הפריט הזה. בתקציב או בחשבון, העמודה היא רק מה שעוד נשאר להוציא בו החודש, לא מה שכבר הוצאת.","המתג **נוכחי / מתוכנן** משנה את התצוגה. שניהם מתחילים מ**בחשבונות שלכם**. **נוכחי** מוריד רק קניות בכרטיס שעוד לא שולמו וחשבונות שעוד לשלם החודש, ולכן מסתיים ב**הכסף שלכם אחרי התשלומים הידועים**: הכסף שלכם היום. קופות, הכרית ומה שנשאר בתקציבים הם תוכניות, ולכן התצוגה הזו לא מורידה אותם. **מתוכנן** מוריד גם את מה שנשאר בתקציבים החודש ואת מה שבצד, ולכן מסתיים ב**פנוי לשימוש**.","העמודה האחרונה היא **פנוי לשימוש** (ירוק): כסף שאף דבר לא צריך. **חסר** (אדום) אומר שמתוכנן יותר ממה שיש לך. לפני יום המשכורת, אם ההכנסה הרגילה שעוד תגיע החודש מכסה את זה, זה לא באדום, ושורה קטנה אומרת בערך כמה יהיה פנוי **אחרי יום המשכורת**.","שורה מעל העמודות מראה את אותו חישוב במילים, מ**בחשבונות שלכם** ועד העמודה האחרונה. **פירוט מלא ←** פותח חלון שמפרט כל סכום בחישוב. כסף שקופה כבר משלמת עליו לא נספר פעמיים."],demo:"waterfall",ex:"₪30,000 בחשבונות. ₪2,000 קניות בכרטיס שעוד לא שולמו ו־₪1,000 חשבונות שעוד צריך לשלם, אז **הכסף שלכם אחרי התשלומים הידועים** הוא ₪27,000. ₪7,000 נשארו בתקציב המכולת. ₪10,000 בצד בקופות. אז **פנוי לשימוש** הוא ₪10,000.",tip:"בין העמודה הראשונה לאחרונה יש לכל היותר 8 עמודות. כשיש יותר תקציבים, הקטנים ביותר מאוחדים לעמודה אחת בשם **אחר**."},
    {h:"הוצאות ותקציבים",p:["**הוצאות לפי קטגוריה** הוא טבעת שמראה לאן הלכו ההוצאות החודש. לחיצה על פרוסה מראה את התשלומים האלה.","**תקציבים** מראה עד 8 תקציבים כפסים, המנוצלים ביותר קודם. הקו הדק על כל פס הוא התאריך של היום בתוך החודש. אם הצבע עבר את הקו, אתה מוציא מהר יותר ממה שהחודש מתקדם. הפס נהיה כתום כשמתקרבים לגבול ואדום כשעוברים אותו."],demo:"budgetbar",ex:"מכולת ₪901 מתוך ₪2,600 ביום 10 מתוך 30. הפס מלא בערך שליש והקו גם בערך בשליש, אז אתה בקצב טוב."},
    {h:"חשבונות לתשלום, אחרונות וקופות",p:["**תשלומים קבועים קרובים** מראה את ארבעת התשלומים הבאים. אלה שעבר זמנם מופיעים ראשונים. הסימן **≈** לפני סכום אומר שהסכום משתנה מחודש לחודש.","**פעילות אחרונה** מראה את חמשת התשלומים האחרונים של החודש (בלי כסף שעבר בין החשבונות שלך). לחיצה על תשלום פותחת אותו.","**קופות** מראה את ההתקדמות של כל קופה וכמה נכנס אליה החודש. למטה, **פנוי לשימוש** הוא הכסף שפנוי עכשיו לקופות.","**היעד שלכם** מופיע רק אחרי ששומרים יעד בתחזית ← השנים הבאות. הוא מראה את היעד, כמה כסף יש בחשבונות שלכם היום (אותו סכום כמו **בחשבונות שלכם**) עם פס, והאם אתם בזמן: אם תחסכו את הממוצע שלכם בכל חודש, האם תגיעו ליעד בזמן? כשאתם באיחור, הוא גם אומר כמה צריך לחסוך בכל חודש כדי להגיע אליו בזמן. לחיצה על הכרטיס פותחת את השנים הבאות."],demo:"bill",ex:"**Netflix** - לתשלום ב‑6 בנובמבר · בעוד 24 ימים - ₪55."},
    {h:"שערי מטבע",p:["אם יש לך כסף במטבע אחר (למשל ב-Wise), הקופסה הזו מראה את השער שלו בשקלים ב-30 הימים האחרונים, עם הנמוך, הממוצע והגבוה. בוחרים מטבע אחר בכפתורים למעלה.","השערים באים מהבנק האירופי המרכזי. משתמשים בהם רק כדי להפוך את היתרות במטבע זר לשקלים. **מטבעות ←** פותח את ההגדרות."],ex:"€1 = ₪4.0000 היום. ה-€500 שלך נספרים כ-₪2,000 בסכומים."}
  ]},

  tx:{title:"על עמוד הפעילות",lead:"הפעילות היא רשימה של כל תשלום שנכנס או יצא, מכל החשבונות שלך. כאן מחפשים משהו, מתקנים קטגוריה או מוסיפים הערה.",blocks:[
    {h:"בשביל מה יש פעילות",p:["תחשוב על זה כמו דף חשבון בנק, אבל לכל החשבונות יחד. החדש ביותר למעלה.","לכסף שנכנס יש **+** לפניו והוא בירוק. לכסף שיצא יש **−** לפניו. אם התשלום היה במטבע אחר, הסכום המקורי מוצג מתחת לסכום בשקלים."],ex:"₪48 בבית מרקחת ב-3 באוקטובר, מ-Max ·· 1234, קטגוריה בריאות."},
    {h:"תשלומים קבועים שכנראה יגיעו ושורות עתידיות",p:["שורות עם התווית **תשלום קבוע שכנראה יגיע**, **עוד לא נראה** או **צפוי** הן תחזיות או פריטים עם תאריך עתידי. לפני הסכום של תשלום קבוע שכנראה יגיע יש **≈**. הן מוצגות כדי שתוכל לתכנן, אבל הן לא נספרות ב'נכנס', 'יצא' או 'נטו', בדוחות, ביתרות או בתקציבים עד שישולמו."]},
    {h:"שלוש לשוניות",p:["**כל הפעילות** היא הרשימה המלאה.","**לבדיקה** מכילה דברים שהאפליקציה לא בטוחה לגביהם. המספר בסוגריים הוא הכמות. ראה **לבדיקה** בהמשך המדריך.","**ייצוא** שומר את התשלומים שלך כקובץ."],demo:"tabs"},
    {h:"חיפוש וסינון",p:["שורת התפריטים הנפתחים למעלה: טווח התאריכים, **כל המקורות** (איזה חשבון), **כל הקטגוריות**, **כל התגיות** ו**כל הסוגים** (הכנסות, משכורת, החזרים כספיים, הוצאות, העברות בין חשבונות, חיובי כרטיס, תשלומים קבועים). **ניקוי מסננים** מאפס את כולם.","טווח התאריכים מתחיל ב**כל התקופה**, והטווח שבוחרים נשמר בדפדפן הזה. בחר **טווח מותאם אישית…** כדי לבחור שני תאריכים.","מתחת לסיכומים, **חיפוש בתוצאות האלה…** מחפש בשם החנות, בתיאור מהבנק, בהערה שלך ובתגיות. לידו, **קיבוץ לפי** מקבץ את הרשימה: לפי יום, שבוע, חודש (הבחירה הראשונה), קטגוריה, סוג, חשבון, עסק או תגית, או **בלי קיבוץ**. כל קבוצה מראה נכנס, יוצא ונטו משלה, ואפשר ללחוץ על הכותרת כדי לסגור אותה. **מיון** מציג קודם את החדש, הישן, הגדול או הקטן ביותר."],ex:"בוחרים **מכולת** ו**החודש**: רואים רק תשלומי מכולת מהחודש."},
    {h:"שורת הסיכומים",p:["מתחת לתפריטים: כמה תנועות אתה רואה, וכן **נכנס**, **יוצא** ו**נטו** שלהן.","ליד המספר, הערה כמו **84 לא נספרות בנכנס וביוצא** אומרת כמה שורות מוצגות אבל לא נוספות: העברות, תשלומי חשבון כרטיס, תשלומים עתידיים, עדכוני יתרה, ושורות שהשארתם בחוץ. מצביעים עליה כדי לראות כל סיבה עם המספר שלה. כך שום דבר לא נספר פעמיים.","החזר כספי לא נוסף ל**נכנס** ולא מוריד את **יוצא**: כשיש כזה, הוא מופיע כסכום נפרד, **החזרים**, לידם."]},
    {h:"איך קוראים שורה",p:["העמודות הן **תאריך**, **תיאור** (החנות), **מ ← אל** (מאיזה חשבון הכסף יצא ולאן הוא הלך), **קטגוריה**, **תגיות**, **סכום** ו**קבצים** (מהדק ומספר כשצירפת קבלה).","אפשר לשנות **קטגוריה** ישר מהשורה. אחר כך האפליקציה מציעה ליצור כלל כדי שהבאים שדומים לו יסתדרו לבד.","תוויות קטנות מסבירות שורות מיוחדות: **תשלום קבוע**, **צפוי**, **תשלום קבוע שכנראה יגיע**, **ממתין** (הבנק עוד לא סיים אותו), **חיוב כרטיס**, **העברה**, **מתעלם**, **עדכון יתרה**, **אולי כפולה**, **קופה · שם**, ו-**3/10** לתשלום בתשלומים (תשלום 3 מתוך 10). מצביעים על תווית כדי לראות מה היא אומרת."]},
    {h:"כסף שנכנס",p:["כסף שנכנס הוא **הכנסה**, חוץ מכסף שנכנס לכרטיס אשראי: הוא **החזר כספי**. שום דבר לא נקבע לפי המילים שבו, ולכן הפקדה בבנק שנקראת \"זיכוי\" והפקדת מזומן הן הכנסה.","תווית קטנה מראה **משכורת** או **החזר כספי**; מצביעים עליה כדי לראות למה (נכנס לכרטיס אשראי, כלל שלכם, או שסימנתם). להכנסה אחרת אין תווית.","הכנסה נספרת ככסף שנכנס, גם משכורת. להחזר כספי יש סכום משלו: הוא לא כסף שנכנס, והקנייה עדיין נספרת במלואה. זיכוי בכרטיס עדיין מוריד את החיוב של הכרטיס.","הסוג לא נכון? פותחים את התשלום ובוחרים **הכנסה**, **משכורת** או **החזר כספי** תחת **מה הכסף הזה?**, או **אוטומטי** כדי שהאפליקציה תחליט שוב. זה נשמר בהיסטוריית השינויים ואפשר לבטל. לכל התשלומים מאותו משלם מוסיפים כלל בהגדרות ← כסף שנכנס."],ex:"המשכורת מגיעה בשם \"זיכוי\": היא נספרת כהכנסה. מסמנים אותה **משכורת** פעם אחת, או מוסיפים כלל עם שם המעסיק, והיא מופיעה כמשכורת."},
    {h:"פתיחת תשלום",p:["לחץ על שם החנות כדי לפתוח את התשלום. אפשר לראות כל פרט שהבנק שלח, לשנות קטגוריה, להוסיף תגיות והערה, ולצרף קבלה.","תחת **פעולות** יש אריחים של לחיצה אחת: **הוספה לתשלומים הקבועים** (האפליקציה תתחיל לצפות לו), **שיוך לקופה** (התשלום יצא מקופה), **סימון כתשלום כרטיס** (זה חשבון כרטיס ולא הוצאה), **לספור בחודש אחר** (להציג אותו בחודש מוקדם או מאוחר יותר בדוחות) ו**להוציא מהסכומים**. מופיעים רק האריחים שמתאימים לתשלום.","לחץ על המהדק כדי לראות קבלות או תמונות שצורפו."],ex:"חיוב של ₪55 מ-Netflix: לוחצים **הוספה לתשלומים הקבועים** והוא מופיע בתשלומים הקבועים."},
    {h:"לבדיקה",p:["**העברות בין החשבונות שלך**: האפליקציה חושבת שכסף עבר מחשבון אחד שלך לאחר. לחץ **אישור**, או **זו לא העברה** אם זו הייתה הוצאה או הכנסה אמיתית. אם נלקחה עמלה, היא מוצגת כעלות.","**אולי כפולות**: אותו סכום, חנות ויום פעמיים. לחץ **מחיקת העותק** או **שמירת שניהם**.","**שינויי יתרה בלי תנועה**: יתרת הבנק זזה אבל אין תשלום שמסביר את זה. בחר **אני יודע מה זה** (להוסיף), **לספור כחיוב** (רק כשהיתרה ירדה), או **לסגור, עם הערה…**."],ex:"יתרת Wise ירדה ב-₪200 בלי תשלום: לוחצים **אני יודע מה זה**, מקלידים את החנות, בוחרים קטגוריה."},
    {h:"ייצוא וצמצום",p:["הלשונית **ייצוא** מורידה את התשלומים שלך כקובץ. היא מתחילה עם המסננים שהיו על הרשימה, ואפשר לשנות אותם שם לפני כן.","לפעמים עמוד אחר שולח אותך לכאן כדי לראות כמה תשלומים מסוימים. קופסה אומרת **מוצגים N פריטים בלבד**. לחץ **הצגת כל הפעילות** כדי לחזור לרשימה המלאה.","רשימות ארוכות נטענות 50 בכל פעם. לחץ **עוד 50** בתחתית."]}
  ]},

  acc:{title:"על עמוד החשבונות",lead:"העמוד הזה מציג כל חשבון שהאפליקציה מכירה: אלה שהיא קוראת מהבנק והכרטיסים שלך, ואלה שהוספת בעצמך. פותחים חשבון כדי לראות את היתרה, גרפים והפעילות שלו.",blocks:[
    {h:"בשביל מה יש חשבונות",p:["האפליקציה מציגה חשבונות מחוברים רק אחרי שחיברת אותם ב**הגדרות ← חיבורים** או ייבאת קובץ. עד אז כתוב בעמוד **עדיין אין חשבונות**, עם **חיבור חשבון** ו**הוספת חשבון**.","החשבונות מקובצים ל**חשבונות בנק**, **כרטיסי אשראי**, **ארנקים** ו**חשבונות אחרים** (אלה שמנהלים בעצמם, ועוד הפנסיה שלך)."],demo:"account",ex:"בנק הפועלים, יתרה ₪23,840, **מחובר**, 123 תנועות."},
    {h:"כרטיסי חשבון",p:["כל כרטיס מראה שם, סוג, יתרה, תווית מצב וכמה תנועות יש בו. כרטיס אשראי מראה מה **חויב החודש** ומה חויב בחודש שעבר, במקום יתרה. מספר כמו **מסתיים ב‑1234** הוא הספרות האחרונות.","אם בהתחברות אחת יש כמה כרטיסים, תקבל חשבון נפרד לכל כרטיס, למשל **Max ·· 1234** ו-**Max ·· 5678**."]},
    {h:"מה המצבים אומרים",p:["**מחובר**: הסנכרון עבד. **לא מעודכן**: לא היה סנכרון יותר מיומיים. **הניסיון האחרון נכשל**: הסנכרון האחרון לא עבד. **נדרש קוד**: הבנק מבקש קוד חד-פעמי. **נעול**: האפליקציה עצרה אותו אחרי שתי כניסות כושלות ברצף (שלוש ב-Wise). **הוזן על ידכם**: את היתרה הזו מעדכנים ידנית. כדי לתקן חיבור פותחים את **הגדרות ← חיבורים**.","האפליקציה יכולה רק לקרוא. היא אף פעם לא יכולה להזיז כסף."],demo:"status"},
    {h:"הוספת חשבון משלך",p:["לחץ **+ הוספת חשבון** ובחר **חשבון שאני מנהל בעצמי**, למשהו בלי חיבור: מזומן, חיסכון במקום אחר, השקעה או הלוואה. (**בנק או כרטיס אשראי** מחבר בנק במקום זה.)","מלא **שם**, **סוג**, **מטבע** ו**יתרה עכשיו**. להלוואה או חוב, הקלד את מה שאתה חייב כמספר שלילי.","שתי אפשרויות: **לספור בשווי הנקי שלי** מוסיף את היתרה לשווי הנקי. **לספור את התנועות שלו בדוחות** מכניס את ההכנסות וההוצאות שלו לדוחות, לתקציבים ולתחזית. כבה את זה אם אתה רוצה רק לעקוב אחרי היתרה."],ex:"חיסכון במיטב, ₪15,000, נספר בשווי הנקי, לא נספר בדוחות."},
    {h:"עדכון יתרה ידנית",p:["בעמוד של חשבון משלך לחץ **עדכון יתרה**, הקלד את היתרה החדשה והערה אם רוצה. היתרה הישנה לא הולכת לאיבוד: היא נשמרת ברשימה **היסטוריית יתרות**.","ב**פעילות** כל עדכון מופיע כהערת **עדכון יתרה**. הוא אף פעם לא נספר כהכנסה או כהוצאה."],ex:"במזומן היו ₪1,000, עכשיו ₪800: עדכון יתרה של ‎−₪200. הדוחות שלך לא משתנים."},
    {h:"עמוד של חשבון אחד",p:["לחץ על כרטיס כלשהו. למעלה: **כל החשבונות** (חזרה לרשימה), **+ הוספת תנועה**, וכפתורים שמתאימים לחשבון. בחשבונות שלך יש **עדכון יתרה**, **עריכה** ו**הסרה**. בפנסיה יש **עדכון יתרה**. בחשבון מחובר יש **למעבר לחיבור ←**.","מתחת תראה אריחים: **יתרה נוכחית**, **נכנס החודש**, **יצא החודש** ו**נטו החודש** (בכרטיס יש **חויב החודש**, **חודש שעבר** ו**היתרה שהכרטיס מדווח**), וגם 12 החודשים האחרונים, מספר התנועות והתנועה האחרונה.","הגרף מראה את היתרה בסוף כל חודש ב-12 החודשים האחרונים, מחושבת אחורה מהיתרה של היום ומהתשלומים. בחשבונות שלך הוא מראה כל פעם שעדכנת (אחרי שעדכנת לפחות פעמיים). בכרטיס הוא מראה **רכישות לפי חודש**."]},
    {h:"פרטים ופעילות",p:["**פרטי החשבון** אומר לך מה הסוג, המטבע, הספק, מצב הסנכרון, מתי היה הסנכרון האחרון, מתי עודכנה היתרה לאחרונה, והאם החשבון נספר בשווי הנקי (ובחשבונות שלך, גם בדוחות).","כרטיסים לא נספרים בשווי הנקי, כי כרטיס הוא חשבון לתשלום ולא כסף שיש לך.","רשימת הפעילות למטה מציגה רק את החשבון הזה. השתמש ב**חיפוש בחשבון הזה…** כדי למצוא תשלום, או ב**פתיחה בפעילות ←** כדי להשתמש בכל המסננים."]},
    {h:"פנסיה",p:["הפנסיה מוסתרת עד שיש לה ערך. מגדירים אותה בכפתור **+** (**יתרת הפנסיה**), ב**עדכון יתרה** בעמוד שלה, או ב**הגדרות ← ייבוא וייצוא**. מעדכנים אותה ידנית.","היא נספרת בשווי הנקי רק אם מפעילים **לכלול פנסיה** בדוחות."]}
  ]},

  jars:{title:"על עמוד הקופות",lead:"קופה היא כיס של כסף בתוך האפליקציה, למטרה או למשהו שתצטרך בהמשך. קופות לא מזיזות כסף אמיתי בבנק. הן רק מזכירות לך מה כבר מיועד.",blocks:[
    {h:"בשביל מה יש קופות",p:["הבנק שלך מראה מספר גדול אחד. קופות מאפשרות לך להגיד: החלק הזה לטיול בקיץ, החלק הזה לחירום.","הכסף נשאר בחשבון. הקופות מתמלאות מהכסף ה**חופשי** שלך, לפי סדר, כך שאף פעם לא תפריש כסף שאין לך באמת."],ex:"בחשבון ₪30,000. בקופה טיול בקיץ יש ₪4,000. עדיין יש לך ₪26,000 שלא מופרשים."},
    {h:"פנוי לשימוש",p:["המספר הגדול למעלה, **פנוי לשימוש**, הוא הכסף החופשי שלך: מה שאין חשבון, תקציב או קופה שצריכים.","הוא החשבונות שלך, פחות קניות בכרטיס שעוד לא שולמו, פחות החשבונות שעוד לשלם החודש, פחות מה שנשאר בתקציבים, פחות מה שבצד (קופות והסכום ששומרים ולא נוגעים בו).","הכנסה שעוד תגיע, כמו המשכורת, נספרת רק כשהיא נכנסת, ולכן לפני יום המשכורת זה יכול להיות ₪0. כשההכנסה הרגילה שעוד תגיע החודש מכסה את הפער, שורה אומרת בערך כמה יהיה פנוי **אחרי יום המשכורת**.","**איך זה מחושב?** פותח רשימה של כל החלקים."],ex:"₪30,000 בחשבונות - ₪2,000 תשלומים קרובים - ₪3,000 שנשארו בתקציבים - ₪15,000 בצד = ₪10,000 פנוי לשימוש.",tip:"אם אתה רואה **₪X יותר מדי.** באדום, הקופות והכרית שלך מסתכמות ביותר ממה שיש לך. שום דבר לא נלקח מקופה מעצמו. הקופות פשוט מפסיקות להתמלא. **החזירו ₪X מהקופות** משחרר את ההפרש."},
    {h:"הכנסה לקופות החודש",p:["הקופסה הזו מראה כמה קיבלו הקופות החודש, מתוך כמה שהן רצו. הפס מתמלא ככל שהן מקבלות כסף.","**נכנס עד עכשיו** הוא מה שקיבלו. **עוד צריך להכניס** הוא מה שעוד חסר להן. **פנוי לשימוש** הוא הכסף החופשי שממנו הן יכולות לקחת. אם הוא אפס, הקופות מחכות עד שיהיה עוד כסף חופשי."],ex:"₪800 מתוך ₪1,200 הוכנסו. עוד ₪400 להכניס. ₪0 פנוי לשימוש: הקופות מחכות."},
    {h:"שמירה בצד",p:["זו הכרית שלך: כסף שהקופות אף פעם לא משתמשות בו. בחר **ללא**, ₪1,000, ₪2,000, ₪5,000 או ₪10,000, או הקלד סכום אחר."],ex:"שומרים ₪5,000 בצד לחירום. הקופות יתמלאו רק מכסף שמעל זה."},
    {h:"הקופות שלך, לפי סדר עדיפות",p:["בכל חודש הקופות לוקחות כסף חופשי לפי סדר. קופה מספר 1 מקבלת ראשונה. משנים את הסדר בחצים שעל הקופה, או בלחיצה על המספר שלה ובחירת מקום.","קופה עם יעד וסכום חודשי לוקחת את הסכום החודשי. קופה עם יעד אבל בלי סכום חודשי לוקחת כל מה שהיא יכולה, עד היעד שלה, לפני שהקופה הבאה מקבלת משהו. קופה בלי יעד ובלי סכום חודשי לא לוקחת כלום בעצמה.","**מילוי עכשיו** ממלא את הקופות מיד מהכסף החופשי. גם בלי ללחוץ, הקופות מתמלאות תוך כדי שנכנס כסף חופשי."],demo:"jar",ex:"טיול בקיץ: ₪4,000 מתוך ₪20,000 (20%), ₪800 בחודש, **תהיה מלאה עד** תאריך שהאפליקציה מחשבת."},
    {h:"איך קוראים כרטיס קופה",p:["מתחת לשם מופיע סוג הקופה, ו**משלמת על** מראה את הקטגוריות שהיא משלמת עליהן, אם יש. הטבעת מראה כמה הקופה מלאה. **נשמר** הוא מה שיש בה (**הוחזר** בהלוואה). **יעד** הוא המטרה (**סך החוב** בהלוואה). **חודשי** הוא הסכום לחודש, או **השלמה** אם היא פשוט לוקחת מה שאפשר. **תהיה מלאה עד** הוא החודש שבו היא אמורה להתמלא.","הלחצן למעלה מראה את המצב החודש: **מומנה**, **מומנה חלקית**, **צריכה ₪X**, **מלאה**, **שולם במלואו** או **בלי מילוי אוטומטי**. לחיצה עליו מראה את ההיסטוריה של הכסף שנכנס ויצא מהקופה.","בתפריט **⋯** יש **עריכת קופה**, **סימון כהושלמה** ו**מחיקת קופה**."],tip:"**תהיה מלאה עד** כנה. היא משתמשת בכסף החופשי שיש לך עכשיו ועוד העודף שהתחזית צופה בכל חודש, בדיוק כמו בעמוד התחזית."},
    {h:"קופה חדשה ויעדים",p:["**+ קופה חדשה** שואלת: בשביל מה זה? **חיסכון** (כסף למשהו: יעד ותאריך לא חובה, ואפשר לקבוע סכום לחודש), **תשלומים קבועים** (שומרים כסף לחשבונות, בחודשים שבחרת) או **החזר הלוואה** (הלוואה שמחזירים: סך החוב, מה שכבר הוחזר, וכמה מחזירים בחודש).","קופת **החזר הלוואה** סופרת למעלה. כשמשלמים את ההלוואה, הקופה לא יורדת: היא מראה כמה כבר הוחזר. כסף שכבר הוחזר, וחיסכון שסימנתם **הכסף הזה לא נמצא בחשבונות שלי כאן**, אף פעם לא מקטינים את הכסף החופשי, כי הכסף הזה לא נמצא בחשבונות","אפשר גם לסמן **משלמת על הקטגוריות האלה**. הוצאות בקטגוריות האלה ירדו אז מהקופה אוטומטית.","רשימת **יעדים** מראה קופות שיש להן סכום יעד (**+ יעד חדש** מוסיף אחד), עם מצב: **בקצב**, **בפיגור**, **בחיסכון**, **הושג** או **ללא סכום חודשי**. **להעלות ל‑₪X בחודש** מתקן קופה שבפיגור. **סימון כהושלמה** סוגר יעד שהושג."],ex:"משלמת על **קניות**: מנורה ב-₪120 מורידה את הקופה ב-₪120."},
    {h:"קופות שהושלמו",p:["קופות שסיימו עוברות ל**קופות שהושלמו**. לחץ **היסטוריה** כדי לראות מה שולם, או **פתיחה מחדש** כדי להשתמש בקופה שוב."]}
  ]},

  bills:{title:"על עמוד התשלומים הקבועים",lead:"תשלומים קבועים הם תשלומים שצפויים לחזור, כמו שכר דירה, טלפון או Netflix. העמוד הזה מוצא אותם לבד, חוזה את התשלום הבא ומתריע כשמשהו נראה לא תקין.",blocks:[
    {h:"בשביל מה יש תשלומים קבועים",p:["האפליקציה עוקבת אחרי התשלומים שלכם. כשאותה חנות מחייבת שוב ושוב, זה הופך לתשלום קבוע, והתשלום הבא נחזה.","הקטגוריה לא משנה. ביטוח רכב הוא תשלום קבוע בכל קטגוריה שהיא."],demo:"bill",ex:"Netflix מחייבת ₪55 ב-6 בכל חודש. האפליקציה מצפה לתשלום הבא ב-6 בנובמבר."},
    {h:"מה נספר ומה לא",p:["תשלומים צפויים ומתקרבים הם **מידע בלבד**. הם לא מתווספים להוצאות או להכנסות, לא משנים יתרה או דוח, ולא מנצלים תקציב. תשלום נחשב להוצאה רק אחרי ששולם בפועל.", "הם כן משפיעים על **פנוי לשימוש** (בבית ובקופות) ועל התחזית: תשלומים שמגיעים **החודש** ועוד לא שולמו (וגם תשלומים באיחור) יורדים, כדי שלא תוציאו כסף שכבר מיועד. תשלומים של החודש הבא מוצגים כאן, אבל עוד לא יורדים."]},
    {h:"שלושת המספרים למעלה",p:["**סך הכול לחודש** הוא כמה התשלומים הקבועים עולים בחודש בממוצע. תשלומים שנתיים מתחלקים על 12 חודשים. השורה הקטנה מראה גם את הסכום השנתי.","**לתשלום ב‑14 הימים הקרובים** מחבר את התשלומים שמגיעים בקרוב, לפי סכומים חזויים.","**שינויי מחיר** מראה כמה יותר (או פחות) משלמים בשנה כי חלק מהתשלומים שינו מחיר."],ex:"Netflix עלתה מ-₪55 ל-₪60. זה ‎+₪5 בחודש, אז **שינויי מחיר** מראה ₪60 בשנה."},
    {h:"ארבעה סוגים",p:["**במועד קבוע**: אותה חנות, לוח זמנים קבוע (כל חודש, כל חודשיים או כל שנה). נמצא אוטומטית.","**במועד משתנה**: המועד משתנה, אבל נקבע שכל תשלום לחנות הזו הוא תשלום קבוע, כמו חשבון מים.","**תשלומים**: קניות ששולמות בחלקים, כמו תשלום 3 מתוך 10, עם כמה נשארו.","**חד‑פעמיים**: תשלום אחד שסומן כתשלום קבוע."]},
    {h:"איך קוראים שורה",p:["בכל שורה יש שם, כל כמה זמן, מאיזה חשבון משולם, והחיוב האחרון. **זוהה אוטומטית** או **נוסף על ידכם** אומר איך הוא הגיע לכאן. הצבעה עליו מראה את התשלומים שעליהם הוא מבוסס.","בסוף השורה הסכום. **≈** אומר שהסכום משתנה, והוא ממוצע של שלושת החיובים האחרונים. מתחתיו: **החיוב הבא ב‑6 בנוב׳**, **בעוד 3 ימים** (כשנשאר שבוע או פחות), **לתשלום עכשיו**, או **באיחור מאז** תאריך.","תווית כמו **▲ ₪5 יותר מהחיוב הקודם** אומרת שהמחיר השתנה."]},
    {h:"תפריט ⋯",p:["**היסטוריה** מראה תשלומי עבר. **הצגה בפעילות** מציגה אותם בפעילות. **שינוי סוג** מחליף בין חודשי, כל חודשיים, שנתי ובמועד משתנה.","**סימון לביטול** מוסיף תווית **סומן לביטול** למנוי שמתכננים להפסיק. אחר כך בוחרים **סימון כבוטל**, או **להשאיר את התשלום הקבוע**.","**הסרה מהרשימה** מפסיקה לעקוב אחריו."],tip:"תשלומים שבוטלו עוברים לרשימה **בוטלו** בתחתית. הם לא נספרים בסכומים, בתחזיות או בהתראות. **שחזור** מחזיר אחד."},
    {h:"הוספת תשלום קבוע ידנית",p:["לוחצים **+ הוספת תשלום קבוע** אם תשלום עוד לא חויב, או שהמועד שלו משתנה.","ממלאים **שם**, **סכום צפוי**, **באיזו תדירות**, **יום בחודש**, **שולם מתוך**, ואם רוצים גם **התאמה לתנועות שמכילות**. כל תשלום שהשם שלו מכיל את הטקסט הזה נספר כחלק מהתשלום הקבוע. אם השדה ריק, נעשה שימוש בשם."],ex:"שם: חדר כושר, ₪250, חודשי, יום 5."},
    {h:"דרכים נוספות ליצור תשלום קבוע",p:["פותחים תשלום כלשהו בפעילות ולוחצים **הוספה לתשלומים הקבועים**. תשלומים כאלה מסומנים בתווית **תשלום קבוע** בפעילות.","תשלום שנתי צריך היסטוריה של שנתיים כדי להימצא, או שמוסיפים אותו ידנית."]}
  ]},

  budg:{title:"על עמוד התקציבים",lead:"תקציב הוא גבול לקטגוריה אחת לחודש אחד, כמו מכולת ₪2,600. העמוד הזה מראה איך אתה עומד מול כל גבול, ועוזר לבחור גבולות הגיוניים.",blocks:[
    {h:"בשביל מה יש תקציבים",p:["תקציבים עונים על שאלה אחת: האם אני מוציא על זה מהר מדי? כל תקציב מתחיל מחדש ב-1 בחודש.","חשבון קבוע שנמצא בקטגוריה הוא חלק מהתקציב שלה. אין צורך לספור אותו פעמיים."],demo:"budgetbar",ex:"תקציב מכולת ₪2,600. הוצאת עד עכשיו ₪901."},
    {h:"מה נספר ומה לא",p:["הסכום ש**הוצא** בתקציב סופר רק תשלומים שקרו בפועל. חיובים צפויים אף פעם לא נספרים כהוצאה.", "**פנוי לשימוש** (בבית ובקופות) שומר בצד את מה שנשאר בתקציבים ואת התשלומים הקבועים שמגיעים **החודש** ועוד לא שולמו (וגם תשלומים באיחור), כדי להראות מה באמת פנוי. תשלום קבוע בקטגוריה שיש לה תקציב הוא חלק מהתקציב, אז נשמר בצד רק הגדול מבין השניים. תשלומים של החודש הבא, ותשלומים שכבר מכוסים בקופה, לא נשמרים בצד."]},
    {h:"המספרים למעלה",p:["**נשאר להוצאה** הוא מה שנשאר מכל התקציבים החודש, עם הערכה כמה זה ליום עד סוף החודש.","**הוצא עד עכשיו** הוא מה שהוצאת בקטגוריות האלה, מתוך כל התקציבים מחוברים. הקו הדק על הפס הוא היום. מתחתיו: אחוז התקציב שנוצל ואחוז החודש שעבר.","**תקציב החודש** הוא כל הגבולות מחוברים. **תקציבים** הוא כמה תקציבים יש לך: כל תקציב הוא קטגוריה אחת."],ex:"₪5,000 בתקציב, הוצאת ₪2,000: נשארו ₪3,000. עם 15 ימים לסוף החודש זה ₪200 ליום."},
    {h:"כרטיס תקציב אחד",p:["כל כרטיס מראה את הקטגוריה, תווית מצב, כמה הוצאת מהגבול, ופס. הקו הדק על הפס הוא היום. אם הצבע עובר אותו, אתה מוציא מהר יותר ממה שהזמן עובר.","מתחת לפס: מה נשאר, כמה ליום, ו**בקצב הזה תוציא** ניחוש לכל החודש.","ליד הסכום, שלושה פסים קטנים מראים מה הוצאת בשלושת החודשים המלאים האחרונים, עם מילה: **בעלייה**, **בירידה** או **יציב**. ההשוואה היא בין החודש המלא האחרון לחודשים שלפניו. שינוי קטן מ-10% (או מ-₪50) נחשב יציב. הצבע עליו כדי לראות את הסכום של כל חודש. חודשים שעברו את הגבול באדום."],ex:"₪400, ₪400, ואז ₪520: החודש האחרון גבוה ב-₪120 מקודם, אז כתוב **בעלייה**."},
    {h:"מה התוויות אומרות",p:["**במסגרת התקציב**: אתה בסדר ובקצב להישאר בפנים.","**צפוי לחרוג**: בסדר היום, אבל בקצב הזה תעבור את הגבול לפני שהחודש נגמר.","**כמעט בגבול**: ניצלת 80% או יותר. אפשר לשנות את האחוז ב-הגדרות ← אילו התראות.","**חריגה של ₪X**: כבר הוצאת יותר מהתקציב."],ex:"גבול ₪2,600, הוצאת ₪901 ביום 10 מתוך 30. קצב: ₪2,703. תווית: **צפוי לחרוג**."},
    {h:"תוספות בכרטיס",p:["**כולל 2 תשלומים קבועים** פותח את רשימת התשלומים הקבועים בקטגוריה. **שולם מקופה** מופיע כשקופה משלמת על הוצאות כאן.","בכפתור **⋯** בכרטיס יש **שינוי הסכום**, **הצגה בפעילות** ו**הסרת התקציב**. ההסרה שואלת קודם, והתשלומים שלך לא נפגעים."]},
    {h:"תקציבים מוצעים",p:["אחרי שני חודשים מלאים של היסטוריה, האפליקציה מציעה תקציבים לפי מה שהוצאת באמת, ועוד בערך 5% מרווח. קטגוריות שרובן חשבונות קבועים מושארות בחוץ.","שנה את הסכום אם בא לך ולחץ **אישור**. **אישור הכול** מקבל את כולם. **לא את זה** מסתיר הצעה. **להציג שוב הצעות שנדחו** מחזיר אותן. שום דבר לא נוצר עד שתאשר."],ex:"הוצאת ₪2,300, ₪2,500 ו-₪2,400 על מכולת. תקציב מוצע: ₪2,550."},
    {h:"רמזים להעלאה או הורדה",p:["לפעמים כרטיס מראה שאלה: חרגת ב-2 מתוך 3 החודשים האחרונים, להעלות? או שאתה מוציא הרבה פחות מהגבול, להוריד?","לחץ **להשתמש ב-₪X** כדי להחיל, או **לא עכשיו**."]},
    {h:"הוצאות בלי תקציב",p:["למטה, **הוצאות בלי תקציב** מפרט קטגוריות שאתה מוציא בהן ואין להן גבול. **קביעת תקציב** יוצרת אחד.","**+ הוספת תקציב** מאפשרת לבחור קטגוריה וגבול חודשי ידנית. הטופס מציע ממוצע של החודשים האחרונים שלך."]}
  ]},

  rep:{title:"על עמוד הדוחות",lead:"הדוחות מראים איך הכסף שלך זז לאורך זמן: שווי נקי, הכנסות, הוצאות, קטגוריות, חנויות ותגיות. משתמשים בהם כשרוצים להבין את העבר, לא כדי לתכנן את העתיד.",blocks:[
    {h:"בשביל מה יש דוחות",p:["כל גרף נבנה מהתשלומים שלך, חודש אחר חודש. העברות בין החשבונות שלך, תשלומי חשבון כרטיס וכל מה שהשארת בחוץ לא נכללים.","**הכנסות** הן כל הכסף שנכנס, גם המשכורת. החזר כספי הוא לא הכנסה ולא מוריד את ההוצאות. אותם מספרים מופיעים בדף הבית.","החודש הנוכחי נספר רק עד היום."],ex:"אוקטובר מראה הוצאות עד היום, לא חודש מלא."},
    {h:"הגרף הראשי",p:["התפריט הראשון בוחר מה להסתכל עליו: **שווי נקי**, **הכנסות**, **הוצאות**, **תזרים נקי (הכנסות − הוצאות)**, **תשלומים קבועים (חוזרים וחד‑פעמיים)**, **קטגוריה** אחת, **מקור הכנסה** אחד או **תגית** אחת.","לידו, **3M**, **6M**, **12M**, **3Y** ו-**הכול** קובעים כמה אחורה להסתכל. המספר הגדול הוא הסה״כ, ובשווי נקי הוא הערך של היום עם השינוי מההתחלה.","מתחת לגרף יש סיכום קטן: סה״כ או עכשיו, ממוצע חודשי או שינוי, החודש הגבוה והנמוך. לחיצה על נקודה בגרף מראה את התשלומים האלה בפעילות."],demo:"forecast",ex:"בוחרים **מכולת** ו-**6M**: רואים 6 עמודות או נקודות, אחת לכל חודש, ואת החודש הממוצע."},
    {h:"סגנון הגרף ואפשרויות",p:["**שטח**, **קו** ו**עמודות** משנים רק את המראה. המספרים אותו דבר.","המתג **השוואה** מצייר את התקופה שלפני בקו מקווקו, כדי לראות אם יש שיפור.","**כולל פנסיה** (רק לשווי נקי) מוסיף את הפנסיה שלך, שאתה מעדכן ידנית. בלעדיו, השווי הנקי הוא רק מזומן והחשבונות שלך שנספרים בשווי נקי."],ex:"שווי נקי, 12M, השוואה פעילה: רואים את הקו של השנה ואת הקו של שנה שעברה."},
    {h:"החודש מול החודש שעבר",p:["הכרטיס הזה משווה את ההוצאות עד עכשיו החודש לאותם ימים בחודש שעבר. לכל קטגוריה שני פסים: החודש למעלה, חודש שעבר מתחת.","קודם מופיעות שתי תיבות: החודש **עד כה**, עם ▲ או ▼ וכמה אחוזים יותר או פחות מחודש שעבר עד אותו יום, וסך ה**חודש המלא** של חודש שעבר, עם כמה ממנו הוצא עד אותו יום."],ex:"ב-10 בחודש הוצאת ₪3,000. בחודש שעבר עד ה-10 הוצאת ₪2,500. התיבה מראה **▲ 20% עד כה**."},
    {h:"הכנסות מול הוצאות",p:["שתי עמודות לכל חודש: **הכנסות** ו**הוצאות**, בצבעים שמופיעים מתחת לגרף. בוחרים כמה חודשים להציג, מ-3 האחרונים ועד כל ההיסטוריה.","לחיצה על עמודה מראה את התשלומים של אותו חודש."]},
    {h:"בתי עסק מובילים ותגיות",p:["**בתי העסק המובילים** מראה את 7 החנויות שהוצאת בהן הכי הרבה. לחץ על שם כדי לראות את כל התשלומים שם. לחץ **✕** אם זו לא חנות אמיתית (בעל בית או חברת כרטיסים). היא מוסתרת ומופיעה ב**מוסתרים מהרשימה הזו**, ומשם אפשר להחזיר אותה.","**הוצאות לפי תגית** מחבר הוצאות לפי תגית, כמו #חופשה. לשניהם יש טווח זמן והשוואה משלהם."],demo:"tags"},
    {h:"הוצאות לפי קטגוריה",p:["טבעת שמראה לאן הלכו ההוצאות. לחץ על פרוסה או על שם כדי לראות את התשלומים האלה.","בחר **טווח זמן** בתפריט שמעל (היום, השבוע, החודש, 30 ימים אחרונים, השנה, מותאם). התפריט השני יכול להשוות **מול התקופה הקודמת** או **מול אותם תאריכים בשנה שעברה**.","כשמשווים, רואים טבלה קטנה: התקופה הזו, הקודמת, והשינוי."],demo:"donut"},
    {h:"מגמת קטגוריות",p:["קווים לחמש הקטגוריות הגדולות שלך לאורך זמן. התפריט הראשון מחליף בין **הוצאות** ל**הכנסות**, והשני בוחר כמה חודשים להציג.","הצבעה על נקודה מראה את המספר שלה. לחיצה על נקודה מראה את התשלומים של אותו חודש."]}
  ]},

  fc:{title:"על עמוד התחזית",lead:"התחזית מנחשת כמה כסף באמת יהיה שלכם בסוף כל חודש, בשנה הקרובה, אחרי תשלום כל מה שקניתם. היא מתחילה ממה שבאמת שלכם בסוף החודש הזה וממשיכה את ההרגלים האחרונים שלכם. זו לא הבטחה.",blocks:[
    {h:"בשביל מה יש תחזית",p:["היא עונה: אם תמשיכו לחיות ככה, כמה יהיה לכם בעוד 3 חודשים, בעוד 6 חודשים, בעוד שנה? האם תרדו אי פעם מתחת לאפס?","אין כאן בינה מלאכותית ואין קסמים. היא מסתכלת על החודשים האחרונים שלכם וממשיכה אותם קדימה, חודש אחרי חודש."],demo:"forecast",ex:"בכל חודש נכנסים ₪18,000 ויוצאים ₪15,000, כך שנשארים לכם ₪3,000. מ-₪30,000 תגיעו לבערך ₪39,000 בעוד 3 חודשים."},
    {h:"הבחירה למעלה",p:["הגרף תמיד מסתכל שנה קדימה. כל נקודה היא היתרה שלכם ביום האחרון של חודש, החל מהחודש הזה.","**מבוסס על**: מכמה חודשים התחזית לומדת: 3 (הרגיל), 6 או 12. 3 שם לב מהר לשינויים. 12 רואה גם הוצאות שנתיות, כמו חגים, אבל שם לב לאט למשכורת חדשה."]},
    {h:"הכללים של התחזית",p:["1. **חודשים:** התחזית לומדת בדיוק ממספר החודשים שבחרתם (3, 6 או 12): החודש הזה והחודשים שלפניו. אותם חודשים לכל שורה, הכנסות והוצאות, בכל יום בחודש. לא משתמשים בשום חודש אחר.","2. **החודש הזה** = מה שבאמת קרה עד היום + מה שבדרך כלל קורה אחרי התאריך של היום. אם משהו שבדרך כלל משולם מאוחר יותר בחודש כבר שולם מוקדם יותר החודש, הוא לא נוסף שוב. משכורת שבדרך כלל מגיעה מאוחר יותר בחודש ועוד לא הגיעה נספרת כאילו היא בדרך.","3. **מה שבדרך כלל קורה אחרי היום** נלמד משני החודשים המלאים שלפני החודש הזה (תמיד שני אלה), מתאריכי התשלום האמיתיים, מקבל תשלום אחרי מקבל תשלום, ומהחשבונות הקבועים שעוד צריך לשלם.","4. **ממוצע** (לחודש) = הממוצע הפשוט של החודשים שמוצגים. חודש בלי כלום נספר כ־₪0. **הכנסות** צפויות להיות בדיוק הממוצע שלהן בכל חודש. ב**הוצאות**, חודש חריג מאוד נמשך קודם לעבר הרגיל.","5. **הוצאות נספרות בחודש שבו קניתם**, גם קניות בכרטיס. התחזית מתחילה מ**הכסף שכנראה יהיה לכם** בסוף החודש הזה: היתרה שכנראה תהיה אז, פחות הקניות בכרטיס של החודש הזה שעוד לא שולמו. כל חודש אחר כך = החודש שלפניו + כסף שנכנס − כסף שיצא.","6. **מגמה:** אם שורת הוצאה עולה או יורדת, זה נחלש בתוך כמה חודשים ולא מתרחק יותר מ־20% מהממוצע. בשורת הכנסה המגמה מוצגת רק לידיעה.","7. **רק בחודש אחד:** שורה שהיה בה כסף רק באחד החודשים שמוצגים צפויה להיות הממוצע שלה בכל חודש.","8. **קופות והתראות** משתמשות באותה תחזית, לפי אותם חודשים שבחרתם."],ex:"היום 20 באוקטובר. שכר דירה של ₪4,000 שולם ב־5 בחודש: אוקטובר נספר ₪4,000. דלק של ₪600 יורד בדרך כלל ב־25, ועד עכשיו שולמו ₪100: אוקטובר נספר ₪600."},
    {h:"מאיפה היא מתחילה",p:["הצעד הראשון הוא סוף החודש הזה: היתרה של היום, פחות החשבונות וחיובי הכרטיס שעוד יירדו החודש, פחות מה שבדרך כלל עוד יוצא אחרי היום, ועוד הכנסות שעוד צפויות החודש (כללים 2 ו־3). אחר כך היא מורידה את הקניות בכרטיס של החודש הזה שעוד לא שולמו: התוצאה היא **הכסף שכנראה יהיה לכם** ביום האחרון של החודש."],ex:"₪20,000 היום, ₪3,000 של חשבונות שעוד צריך לשלם, ₪1,000 שבדרך כלל עוד יוצאים אחרי היום ומשכורת של ₪8,000 שעוד בדרך: בערך ₪24,000 בסוף החודש."},
    {h:"איך מחושב כל חודש",p:["בכל חודש: הכסף שכנראה יהיה לכם בסוף החודש הקודם, ועוד הכסף שנכנס, פחות הכסף שיוצא (קניות בכרטיס נספרות בחודש שבו קניתם).","כל הכנסה מוצגת בשם שנתתם לה, או לפי מי ששלח אותה, או לפי הקטגוריה שלה. הכנסה שהגיעה רק בחלק מהחודשים נספרת כממוצע שלה על פני כל החודשים (כלל 4).","**הוצאות** מחושבות לכל קטגוריה, באותה דרך.","הכרטיס **איך מחושב החודש הבא** מראה את זה בארבעה צעדים: **היום** (הכסף בחשבונות שלכם), היום האחרון של החודש הזה, מה שהחודש הבא כנראה מוסיף (כסף שנכנס − כסף שיוצא), והיום האחרון של החודש הבא: לאן תגיעו."],ex:"₪16,800 נכנסו בספטמבר ובאוקטובר, 2 מתוך 3 החודשים האחרונים: זה נספר כ־₪11,200 בחודש. הקניות בכרטיס באוקטובר משולמות בנובמבר, אבל הן כבר יורדות ב־31 באוקטובר, כך שכל חודש רק מוסיף את מה שהוא חוסך."},
    {h:"על מה זה מבוסס",p:["כותרת החודשים בטבלה (למשל **אוג׳ – אוק׳**) אומרת מאילו חודשים התחזית לומדת.","תשלומי חיוב כרטיס מהבנק לא נספרים כהוצאה, כי הקניות כבר נספרות בכרטיס.","הערה אדומה מופיעה אם בחודש מסוים לא הייתה הכנסה. אז אולי חסר משהו בהיסטוריה. נסו **ייבוא היסטוריה** בהגדרות ← חיבורים."]},
    {h:"ארבעה כרטיסי יתרה",p:["**סוף** החודש הזה, **בעוד 3 חודשים**, **בעוד 6 חודשים** ו**בעוד שנה**. כל מספר הוא **הכסף שכנראה יהיה לכם** אז: היתרה אחרי תשלום על כל מה שכבר קניתם (קניות בכרטיס שעוד לא שולמו ותשלומים שכבר צריך לשלם יורדים). הכרטיס הראשון הוא הסכום הצפוי ביום האחרון של החודש הזה, אחרי החשבונות לתשלום וההוצאות הרגילות שעוד צפויות; באותיות קטנות, כמה יש בבנק היום. האחרים מראים את השינוי מסוף החודש הזה ואיפה היא **כנראה** תהיה.","ככל שמסתכלים רחוק יותר, הטווח הזה רחב יותר, כי העתיד פחות בטוח."],ex:"בעוד 6 חודשים: ₪48,000, ▲ ₪18,000, כנראה בין ₪44,000 ל-₪52,000."},
    {h:"הגרף",p:["הקו הוא הכסף שכנראה יהיה לכם. האזור המוצלל (**טווח צפוי**) הוא איפה היא כנראה תהיה. עברו עם העכבר על הגרף כדי לראות את המספר של חודש.","הפס מראה כמה התוצאה החודשית שלכם (כסף שנכנס − כסף שיצא) השתנתה מחודש לחודש בחודשים שבחרתם. אם החודשים שלכם דומים, למשל ₪10,000 נכנסים כל חודש וההוצאות נשארות בערך אותו דבר, הפס צר. אם הם שונים מאוד, למשל תשלום גדול בחלק מהחודשים וכמעט כלום באחרים, הפס רחב. הוא מתרחב ככל שמסתכלים רחוק יותר, כי קשה יותר לצפות חודשים מאוחרים.","תווית מספרת את הסיפור: **נשאר חיובי לאורך כל הטווח**, **עלולה לרדת מתחת לאפס בסביבות** חודש, או **היתרה הצפויה הופכת שלילית ב**חודש. הקו האדום המקווקו הוא אפס."]},
    {h:"מה מניע את התחזית",p:["טבלה של כסף שנכנס וכסף שיוצא. לכל שורה יש עמודות קטנות, אחת לכל חודש שממנו היא לומדת, מהישן לחדש. העמודה של החודש הזה מפוספסת: החלק המלא כבר קרה, והחלק המפוספס בדרך כלל עוד קורה אחרי היום. עברו על עמודה כדי לראות את החודש והסכום, או הקישו על העמודות של השורה כדי לראות את הסכום המדויק של כל חודש.","אחר כך: **ממוצע** (לחודש), **כנראה** (בחודש הבא; הכנסות: הממוצע שלהן; הוצאות: הממוצע, שמשתנה רק אם השורה עולה או יורדת), **סה״כ** (12 החודשים הבאים) ו**מגמה** (עולה, יורד או יציב; **—** כשהיה בשורה כסף רק באחד החודשים, מעט מדי כדי לדעת). עברו על כותרת עמודה כדי לראות מה היא אומרת.","למטה: **כנראה ייחסך בכל חודש** (כסף שנכנס פחות כסף שיוצא, כפי שהתחזית מצפה) ו**הכסף שכנראה יהיה לכם בסוף החודש**: הכסף שלכם בסוף החודש הבא, ואחרי 12 חודשים, אותם מספרים כמו בגרף.","לחצו על שם כדי לראות את התשלומים שלו."],ex:"מכולת, עם עמודות לאוג׳, ספט׳ ואוק׳: ₪3,000, ₪3,000, ו־₪2,000 עד עכשיו (בדרך כלל ₪3,000). **ממוצע** ₪3,000 לחודש."},
    {h:"תחזית קופות",p:["לכל קופה, גרף קטן מראה כמה יהיה בה עם הזמן ומתי היא תהיה **מלאה**. היא יכולה להשתמש רק בכסף שבאמת פנוי: הכסף החופשי היום ועוד מה שכל חודש מוסיף בתחזית, מחולק לפי עדיפות. היא משתמשת באותם חודשים כמו הגרף הראשי.","מניחים שקופות של תשלומים קבועים נשארות מלאות. אם כתוב **אחרי המועד** או **לא בתוך 5 שנים**, הקופה צריכה עוד כסף או עוד זמן. הקו המקווקו הוא היעד."],demo:"jar",ex:"לטיול בקיץ חסרים עוד ₪16,000, והכסף החופשי גדל ב-₪1,000 בחודש: מלאה בעוד בערך 16 חודשים."},
    {h:"השנים הבאות",p:["בתחתית דף התחזית: כמה הכסף שלכם יכול להצטבר לאורך הרבה שנים. החישוב מתחיל מ**בחשבונות שלכם** (אותו סכום כמו בדף הבית, בלי הפנסיה) ומוסיף את **הממוצע שלכם**: מה שנכנס פחות מה שיצא בכל אחד מהחודשים המלאים האחרונים, בממוצע. החודש הזה לא נספר עד שהוא נגמר, וגם לא העברות בין החשבונות שלכם, תשלומי חיוב כרטיס (הקניות עצמן נספרות), תשלומים שעוד לא הגיעו ושורות שהוצאתם מהחשבון. כמה חודשים: הבחירה ב**מבוסס על** בראש דף התחזית.","שלוש התיבות תמיד מתאימות לארבע הבחירות (**היעד שלכם**, **חיסכון בכל חודש**, **עד גיל** ו**גידול בכל שנה**): **עד גיל** (כמה יהיה לכם עד אז), **מגיעים** ליעד (בערך באיזה גיל) ו**צריך עד גיל** (כמה לחסוך בכל חודש כדי להגיע בזמן). הצביעו על שם התיבה כדי לראות איך זה מחושב. הממוצע שלכם מופיע מתחת ל**חיסכון בכל חודש**; כשהסכום שונה ממנו, התיבה **מגיעים** אומרת בכמה מוקדם או מאוחר יותר, הגרף מראה את הממוצע שלכם בקו מקווקו, ו**חזרה לממוצע שלי**, בסוף הכותרת **חיסכון בכל חודש**, מחזיר אותו. את הסכומים ואת הגיל אפשר להקליד בתיבות או לבחור במחוונים. המחוון של **חיסכון בכל חודש** הולך מ-₪0 עד סכום עגול שתלוי רק בממוצע שלכם, ולכן הוא לא משתנה כשהגיל או היעד משתנים; אפשר עדיין להקליד סכום גדול יותר.","עם **הגיל** שלכם מהגדרות ← פרופיל, התיבות אומרות גיל (**עד גיל 50: ₪616,000**), עד גיל 100. בלי גיל, הן סופרות בשנים מהיום. הבחירות האחרונות נזכרות לפעם הבאה.","**גידול בכל שנה** הוא רק הערכה. 0% אומר שהכסף לא גדל: הוא נשאר אותו דבר, כמו כסף בחשבון בנק רגיל. 3% זה בערך מה שחיסכון איטי ובטוח עשוי לתת, כמו תוכנית חיסכון או פיקדון בבנק; 5% זה בערך מה שכסף שמושקע לשנים רבות עשוי לתת, כמו קרן פנסיה, קרן השתלמות או מניות. הגידול האמיתי יכול להיות יותר, פחות, או שהכסף אפילו ירד. כל חודש מקבל את החלק שלו מהגידול השנתי, כך ש־12 חודשים יחד גדלים בדיוק בשיעור הזה.","**שמירת היעד** שומרת את היעד, את החיסכון בכל חודש, את הגיל (או את מספר השנים) ואת הגידול. אחר כך דף הבית מראה כרטיס **היעד שלכם**. כשפותחים שוב את התחזית, הבחירות מתחילות מהיעד השמור. אחרי שיעד נשמר, **עדכון היעד** שומר את הבחירות כמו שהן עכשיו (אפשר ללחוץ עליו רק כשהן שונות מהיעד השמור), ו**הסרת היעד** מסירה את היעד אחרי שאלה. כל אחת מהפעולות האלה נרשמת בהיסטוריית השינויים ואפשר לבטל אותה."],ex:"₪40,000 בחשבונות, ממוצע של ₪3,000 שנשארים בחודש, גיל 34, יעד ₪1,000,000 עד גיל 50: בלי גידול יהיו לכם בערך ₪616,000 עד גיל 50 ותגיעו ליעד בערך בגיל 61; כדי להגיע לשם עד גיל 50 צריך בערך ₪5,000 בחודש."},
    {h:"מה נשאר בחוץ",p:["הפנסיה לא נכללת בתחזית. הוצאה חד-פעמית, כמו טיול, נספרת רק אם היא קרתה בחודשים שהתחזית לומדת מהם. אז היא מתחלקת שווה על כל חודש: ₪955 חד-פעמיים ב־3 חודשים נספרים כ־₪318 בכל חודש. התחזית אינה ייעוץ."]}
  ]},

  alerts:{title:"על עמוד ההתראות",lead:"התראות הן הודעות קצרות על דברים שאולי דורשים אותך: תשלום קבוע שמגיע, תקציב שהגיע לגבול, תשלום שנראה מוזר. הן אומרות לך על מה להסתכל, ולא משנות שום דבר.",blocks:[
    {h:"בשביל מה יש התראות",p:["האפליקציה בודקת את הנתונים שלך ומציגה התראה כשמשהו צריך מבט. המספר ליד **התראות** בתפריט הוא כמה מוצגות עכשיו.","עד שלוש מופיעות גם בראש מסך הבית."],demo:"alert"},
    {h:"שתי לשוניות",p:["**התראות** מראה מה דורש תשומת לב ממש עכשיו.","**היסטוריה** מראה כל התראה שהופיעה אי פעם, מתי הופיעה ומתי נעלמה."],demo:"tabs"},
    {h:"איך קוראים התראה",p:["הנקודה הצבעונית מראה כמה זה דחוף. אחריה כותרת, שורה קצרה עם המספרים, מתי הופיעה, ושני כפתורים.","**פתיחה** לוקח אותך למקום הנכון (התשלום הקבוע, התקציב, התשלום). **סגירה** מסתירה אותה. התראה שנסגרה לא חוזרת, אלא אם זו התראה חדשה. **הצגה מחדש של התראות שנסגרו** בהגדרות ← אילו התראות מחזיר את כולן."],ex:"**Netflix לתשלום בעוד יומיים** - בערך ₪55. לוחצים **פתיחה** כדי לראות את התשלום הקבוע."},
    {h:"סוגי התראות",p:["תשלומים קבועים שמגיעים בקרוב או באיחור, שינויי מחיר בתשלומים קבועים, תקציבים שכמעט נוצלו, צפויים לחרוג או נחצו, חיוב כרטיס גבוה בהרבה מחודש שעבר, תשלום גדול, העברות וכפילויות לבדיקה, חיובים בכרטיס שעדיין ממתינים אחרי 5 ימים, יתרה ששונתה בלי תשלום שמסביר את זה, מקור שלא מעודכן, תשלומים בלי קטגוריה, תחזית שיורדת מתחת לאפס, הכנסה בלי מסמך, קופה שנגמרה, ותשלומים שנראים כאילו באו מקופה.","אפשר להפעיל או לכבות כל סוג, ולחלקם יש גבולות שאפשר לשנות."]},
    {h:"לשונית ההיסטוריה",p:["כל שורה מראה **פעילה**, **נפתרה** (הבעיה נעלמה מעצמה) או **נסגרה** (הסתרת אותה). רואים גם מתי הופיעה וכמה זמן נמשכה.","לחץ **עוד** כדי ללכת אחורה יותר."],ex:"הופיעה 3 באוקטובר, 09:00 - נעלמה 5 באוקטובר, 18:00 (יומיים)."},
    {h:"שינוי מה שמקבלים",p:["**הגדרות התראות ←** פותח את הגדרות ← אילו התראות, שם בוחרים את הסוגים ואת הגבולות.","לאן ההתראות נשלחות (הטלפון, טלגרם וכן הלאה) מגדירים בהגדרות ← לאן נשלחות התראות."]}
  ]},

  cats:{title:"על עמוד הקטגוריות",lead:"קטגוריה היא תווית לתשלום, כמו מכולת או שכר דירה. קטגוריות הופכות את הגרפים, התקציבים והתחזית שלך למשמעותיים.",blocks:[
    {h:"בשביל מה העמוד הזה",p:["רואים לאן הולך הכסף, לפי קטגוריה ולפי תגית. שתי לשוניות: **קטגוריות** ו**תגיות**.","קטגוריות הן התווית הראשית, אחת לכל תשלום. תגיות הן תוויות נוספות, כמה שרוצים.","הכללים שממיינים תשלומים בשבילך נמצאים ב**הגדרות ← מיון אוטומטי**. **למעבר לכללי הקטגוריות** ו**למעבר לכללי התגיות** מובילים לשם."],demo:"tabs"},
    {h:"כל שורה",p:["בוחרים למעלה **3, 6 או 12 חודשים**. נספרים רק חודשים מלאים.","מעל הרשימה: **יצא**, **נכנס** ו**נכנס פחות יצא** בחודשים שנבחרו. כל שורה מראה **החודש**, **חודש שעבר**, **חודש רגיל** (הממוצע לחודש), **יצא ב־6 חודשים** (מספר החודשים שנבחר), **שינוי** (לעומת אותו מספר חודשים לפני כן) ו**תקציב**.","**בחירת עמודות** (הכפתור בסוף כותרות העמודות) מוסיף או מסתיר עמודות, כמו **נכנס ב־6 חודשים**, **תנועות** או **כללים**. לחיצה על כותרת עמודה ממיינת לפיה.","כסף שעבר בין החשבונות שלך ותשלומי חשבון כרטיס לא נספרים, כמו בדוחות.","לחיצה על שורה מראה את התשלומים האחרונים בה וגרף קטן, חודש אחרי חודש. **הכול בפעילות** מראה את כל התשלומים בה."],ex:"קניות מזון: ₪1,500 יצאו ב־6 חודשים, חודש רגיל ₪250, ₪120 פחות מ־6 החודשים שלפני."},
    {h:"הוספה, שינוי שם או מחיקה",p:["כותבים שם ולוחצים **+ הוספת קטגוריה** כדי ליצור חדשה. בלשונית תגיות, **+ הוספת תגית** עושה אותו דבר לתגית.","בכפתור **⋯** בשורה יש **שינוי שם או מיזוג** (אם השם החדש כבר קיים, השתיים מתאחדות) ו**מחיקה**. מחיקה אף פעם לא מוחקת תשלומים: התשלומים של קטגוריה שנמחקה נשארים בלי קטגוריה.","אפשר להוסיף תגית גם כשפותחים תשלום, או בכלל תגית."]},
    {h:"איפה משתמשים בתגיות ובקטגוריות",p:["בוחרים אותן ב**פעילות** (סינון וקיבוץ), ב**דוחות** (הוצאות לפי קטגוריה ולפי תגית) וב**תקציבים**. אפשר גם לתת תגית או קטגוריה לתשלום כשפותחים אותו."]}
  ]},

  "set.conn":{title:"על החיבורים",lead:"כאן מחברים את הבנקים, הכרטיסים ו-Wise כדי שהאפליקציה תקרא את התשלומים שלך לבד. האפליקציה היא לקריאה בלבד: היא יכולה להסתכל, אבל לא להזיז כסף.",blocks:[
    {h:"בשביל מה הלשונית הזו",p:["מוסיפים כל בנק או כרטיס שאתה משתמש בו. רק מה שהוספת מוצג ומסתנכרן.","פרטי ההתחברות שלך נשמרים מוצפנים ולא מוצגים שוב. שתי כניסות כושלות עוצרות מקור, כדי שהבנק לא יינעל לך."],demo:"status"},
    {h:"הוספת חיבור",p:["לוחצים **+ הוספת חיבור**, בוחרים בנק, כרטיס או ארנק ברשימה ולוחצים **הוספה**. מופיע כרטיס עם שדות לפרטי ההתחברות, **כינוי (לא חובה)**, **שמירה** ו**ביטול**.","הבנק לא ברשימה? לוחצים **ייבוא קובץ** כדי להביא במקום זה קובץ מהבנק (הגדרות ← ייבוא וייצוא)."],ex:"לוחצים **+ הוספת חיבור**, בוחרים **Max**, לוחצים **הוספה**, מקלידים פרטי התחברות ולוחצים **שמירה**."},
    {h:"שתי התחברויות באותה חברה",p:["יש לך שני חשבונות Wise, או שתי קבוצות כרטיסים? בחר שוב את אותה חברה מהרשימה (כתוב “התחברות נוספת”) ותן לכל אחת כינוי כדי להבדיל ביניהן. הכינוי חובה בשנייה."],ex:"Wise · עסקי ו-Wise · אישי."},
    {h:"כרטיס מחובר",p:["אחרי החיבור, הכרטיס מראה את המצב שלו למעלה, ואחר כך **סנכרון אחרון**, **אימות כניסה** ו**חשבונות שנמצאו** עם היתרות שלהם. **אימות כניסה** מראה את היום שבו הוא בוצע, או את היום של הסנכרון הראשון שהצליח. ב-Wise אין **אימות כניסה**.","**סנכרון עכשיו** קורא את החיבור הזה מיד. **עריכת חיבור** פותח את ההגדרות (ו**הסתרת ההגדרות** סוגר אותן)."]},
    {h:"בתוך עריכת חיבור",p:["**כינוי** ושדות ההתחברות. התחברויות שמורות מוצגות כ“שמור · הקלידו כדי להחליף”. **שמירה** שומרת שינויים.","**אימות כניסה** הוא לבנקים שמבקשים קוד חד-פעמי. הוא פותח את הדפדפן של האפליקציה, מוצג בשידור חי: התחבר, הקלד את הקוד, סמן “זכור את המכשיר” ולחץ **סיום**. הבנק מכיר אז את הדפדפן הזה, ולכן סנכרונים אוטומטיים לא אמורים לבקש שוב. ב-Wise אין בזה צורך.","**בדיקת חיבור** בודקת את ההתחברות בלי לשמור כלום. **ביטול נעילה** מופיע אם המקור נעצר. **הסרה** מנתקת אותו."],tip:"ב-Wise: צור טוקן אישי עם הרשאות קריאה בלבד."},
    {h:"קריאה רחוק יותר אחורה",p:["ליד **סנכרון עכשיו** בכרטיס מחובר בוחרים כמה אחורה לקרוא. הבחירה הראשונה היא הסנכרון הרגיל (התקופה שנקבעה בסנכרון אוטומטי, למשל **30 הימים האחרונים**).","בחר **שנה**, **שנתיים** או **5 שנים** ולחץ **סנכרון עכשיו** כדי לקרוא רחוק יותר אחורה, פעם אחת. האפליקציה שומרת מה שהבנק עדיין מחזיק. שום דבר שכבר באפליקציה לא נוסף פעמיים. אחר כך הבחירה חוזרת לתקופה הרגילה."],ex:"התחברת היום ויש לך רק שנה אחת. בוחרים **5 שנים** ולוחצים **סנכרון עכשיו** כדי לקבל תשלומים ישנים יותר."},
    {h:"מצבים",p:["**מחובר**, **לא מעודכן**, **הניסיון האחרון נכשל**, **נעול**, **נדרש קוד**, **לא נבדק**, **נבדק · עוד לא סונכרן**, **אין פרטי התחברות**. שורה מתחת לשם מסבירה את המצב ומה לעשות.","כשהתחברות נכשלה, **איפה זה נעצר** מראה תמונה של דף הבנק ברגע שזה נעצר."]}
  ]},

  "set.sync":{title:"על הסנכרון האוטומטי",lead:"סנכרון הוא הדרך שבה האפליקציה מביאה תשלומים ויתרות חדשים מהחיבורים שלך. הלשונית הזו קובעת מתי זה קורה ומראה יומן של כל סנכרון.",blocks:[
    {h:"בשביל מה יש סנכרון",p:["השרת מסנכרן לבד, גם כשהאפליקציה סגורה. פתיחת האפליקציה אף פעם לא מתחילה סנכרון.","תמיד אפשר ללחוץ **סנכרון עכשיו**: בכרטיס בחיבורים, בתפריט + או בחלון הסנכרון שבתפריט הצד."],demo:"sync"},
    {h:"כל כמה זמן",p:["בוחרים **פעם ביום**, **פעמיים ביום**, **כל 8 שעות**, **כל 6 שעות**, **כל 4 שעות**, או **אף פעם, רק כשאני לוחץ על ״סנכרון עכשיו״**.","אחר כך קובעים את **שעה ביום** (או **סנכרון ראשון ב‑**). **הסנכרון הבא** מראה מתי יהיה הבא ומתי רץ האחרון האוטומטי."],ex:"כל 8 שעות, הראשון ב-06:00: מסתנכרן ב-06:00, 14:00 ו-22:00."},
    {h:"כמה אחורה כל סנכרון קורא",p:["**כמה אחורה כל סנכרון קורא**: שבועיים, 30 יום, 60 יום או 90 יום. קצר יותר מהיר יותר ועדין יותר לבנק.","**כמה אחורה קורא בנק או כרטיס חדש**: מ-3 חודשים עד 5 שנים. זה נעשה פעם אחת כשמתחברים. הבנק מחליט כמה הוא עדיין שומר, בדרך כלל שנה עד שנתיים."],ex:"סנכרון רגיל של 30 יום: בכל פעם בודקים את 30 הימים האחרונים ומוסיפים תשלומים חדשים. ישנים לא מוכפלים."},
    {h:"סנכרונים קודמים",p:["מתחת להגדרות: כל סנכרון, עם שם החיבור, **הצליח**, **נכשל** או **פועל**, מתי רץ, **אוטומטי** או **ידני**, וכמה זמן לקח.","**התבקש** הוא התקופה שהתבקשה. **הוחזר** הוא כמה עסקאות חזרו ועד כמה אחורה. **חדש** הוא כמה היו חדשות לאפליקציה. כשל מראה את הסיבה."],tip:"לחץ **רענון** כדי לעדכן את הרשימה, או **עוד 50** בתחתית."},
    {h:"אם משהו נכשל",p:["שורה שנכשלה מראה את הסיבה ממש מתחתיה. בנק שמבקש קוד צריך **אימות כניסה** בחיבורים. מקור נעול צריך בדיקה של פרטי ההתחברות, ואז **ביטול נעילה**.","כפתור הסנכרון בתחתית תפריט הצד פותח את **מקורות**, רשימה של כל החיבורים עם נקודה צבעונית: ירוק מחובר ומסונכרן, כתום לא מחובר או ממתין, אדום נכשל או נעול."]}
  ]},

  "set.data":{title:"על ייבוא וייצוא",lead:"מביאים תשלומים מקובץ, או מוציאים את הנתונים שלך. הכול נשאר בשרת שלך.",blocks:[
    {h:"בשביל מה הלשונית הזו",p:["אם בנק לא מחובר, או שאתה רוצה היסטוריה ישנה יותר, אפשר לייבא קובץ CSV. אפשר גם לייצא את הנתונים בכל זמן."]},
    {h:"ייבוא",p:["**ייבוא CSV של Wise** מוסיף דף חשבון של Wise. **בחירת קובץ CSV** מוסיף ייצוא מבנק או כרטיס: קודם בוחרים את ה**חשבון** שהוא שייך אליו.","מפעילים את **החיובים הם מספרים חיוביים** אם קובץ הכרטיס שלך מציג הוצאות כמספרים עם פלוס.","שורות שכבר יובאו מדלגים עליהן. שורות שתואמות תשלומים שהקלדת ידנית ממוזגות. שום דבר לא מוכפל."],ex:"מייבאים דף חשבון בן שנתיים: מתווספים רק התשלומים שעדיין אין לך."},
    {h:"פנסיה",p:["**עדכון יתרת הפנסיה** הוא המקום שבו מקלידים את הפנסיה. היא מוזנת ידנית."]},
    {h:"ייצוא",p:["**ייצוא…** פותח את לשונית **ייצוא** בפעילות: מה לייצא, התקופה, קטגוריות, חשבונות, סוג, טקסט, תגית, אילו פריטים נוספים לכלול (העברות, תשלומי חשבון כרטיס, עתידיים) והעמודות. רואים תצוגה מקדימה, ואז בוחרים **CSV** (נפתח באקסל או ב-Sheets) או **JSON**.","הקובץ נוצר על המכשיר הזה. שום דבר לא נשלח לשום מקום."]},
    {h:"ייצוא מלא",p:["**הורדת הייצוא** שומרת הכול בקובץ JSON אחד, לקריאה או לשמירה.","כדי לשחזר מגיבוי, או לעבור למכשיר חדש, לוחצים **גיבוי ושחזור**. הגיבויים היומיים האוטומטיים נמצאים שם."]}
  ]},

  "set.alr":{title:"על אילו התראות",lead:"בוחרים אילו סוגי התראות אתה רוצה, וכמה הן רגישות.",blocks:[
    {h:"בשביל מה הלשונית הזו",p:["לא כולם רוצים כל התראה. כאן מפעילים או מכבים כל סוג. ההתראות שאתה מקבל מופיעות בעמוד ההתראות ובראש מסך הבית."]},
    {h:"אילו התראות להציג",p:["מתג אחד לכל סוג: תשלומים שנראים כאילו באו מקופה, חשבונות שמגיעים או באיחור, שינויי מחיר בחשבונות, גבולות תקציב, חיוב כרטיס גבוה בהרבה מחודש שעבר, עסקאות גדולות, העברות וכפילויות לבדיקה, ספרים שלא תואמים לבנק, חיובים שעדיין ממתינים אחרי 5 ימים, מקור שלא מעודכן, עסקאות בלי קטגוריה, תחזית שהופכת שלילית, והכנסות בלי מסמכים.","מכבים מתג והסוג הזה מפסיק להופיע ומפסיק להישלח."],demo:"alert"},
    {h:"הסכום שמתחת למתג",p:["**חיוב כרטיס גבוה ב-(%)**: להתריע כשכרטיס החודש גבוה מחודש שעבר ביותר מהאחוז הזה. מתחיל ב-10.","**תנועה גדולה מ‑(₪)**: להתריע על כל תשלום בגודל הזה ב-7 הימים האחרונים. מתחיל ב-₪5,000.","**תזכורת לתשלום קבוע (ימים לפני)**: להתריע כמה ימים לפני תשלום קבוע. מתחיל ב-3.","**אזהרת תקציב ב-(%)**: להתריע כשתקציב מנוצל בכמות הזו. מתחיל ב-80."],ex:"אזהרת תקציב ב-80, מכולת ₪2,600: תקבל אזהרה ב-₪2,080."},
    {h:"הדחוף ראשון",p:["ההתראות ממוינות לפי כמה הן דחופות. חשבון שבאיחור או תקציב שכבר נחצה מופיעים ראשונים. חשבון שמגיע בקרוב או תקציב ברמת האזהרה אחריהם. שינויי מחיר, תשלומים גדולים ופריטים בלי קטגוריה בסוף."],ex:"**נראה ש-Netflix באיחור** מופיע מעל **12 עסקאות צריכות קטגוריה**."},
    {h:"נסגרו בטעות",p:["**הצגה מחדש של התראות שנסגרו** מחזירה התראות שהוסתרו. **למעבר להתראות** פותח את העמוד.","לאן ההתראות נשלחות מוגדר בלשונית לאן נשלחות התראות."]}
  ]},

  "set.notify":{title:"על שליחת ההתראות",lead:"בוחרים לאן ההתראות נשלחות כשאתה לא מסתכל באפליקציה: הטלפון, טלגרם או שירות אחר.",blocks:[
    {h:"בשביל מה הלשונית הזו",p:["התראות תמיד מופיעות בתוך האפליקציה. כאן אפשר לקבל אותן גם מחוץ לה. כשהאפליקציה סגורה, השרת שולח אותן למקומות שמפעילים בעמוד הזה."]},
    {h:"במכשיר הזה",p:["מפעילים את **להציג התראות במכשיר הזה** וההתראות קופצות על המסך הזה כשהאפליקציה פתוחה. **שליחת בדיקה** מציגה אחת מיד, כדי לדעת שזה עובד.","אם הדפדפן חוסם התראות, קודם מאשרים אותן בהגדרות הדפדפן או המחשב."]},
    {h:"התראות ברקע",p:["מפעילים את **התראות גם כשהאפליקציה סגורה** והמכשיר הזה מקבל התראות גם כשהאפליקציה סגורה. **שליחת בדיקה** בודקת את זה.","צריך לפתוח את האפליקציה בכתובת מאובטחת (כזו שמתחילה ב-https). בטלפון, קודם מוסיפים את האפליקציה למסך הבית.","באפליקציית ה-Android החלק הזה נקרא **התראות בטלפון הזה**, עם מתג אחד: **להציג התראות כהתראות בטלפון**."]},
    {h:"טלגרם",p:["ההתראות מגיעות כהודעות בטלגרם. יוצרים בוט עם @BotFather ומדביקים את **מפתח הבוט**. אחר כך מוסיפים את **מספר הצ׳אט**: שולחים הודעה לבוט ומסתכלים בעמוד getUpdates.","לוחצים **שמירה**. הסטטוס הופך ל**פעיל**. **שליחת בדיקה** בודקת. **הסרה** מכבה."]},
    {h:"Webhook",p:["Webhook שולח התראות ל-Discord, Slack, Home Assistant, n8n ודומים. מדביקים את **כתובת אינטרנט** ולוחצים **שמירה**. **שליחת בדיקה** ו**הסרה** עובדות באותו אופן."]},
    {h:"ntfy",p:["ntfy הוא שירות התראות חינמי שאפשר להריץ על השרת שלכם. מקלידים את **הכתובת שלכם ב‑ntfy** ולוחצים **שליחת בדיקה ל‑ntfy**. לא חובה."]},
    {h:"פרטיות",p:["טלגרם ו-Webhook שולחים את טקסט ההתראה, עם שמות חשבונות וסכומים, דרך האינטרנט לשירות הזה. הפעל אותם רק אם זה בסדר מבחינתך.","אילו סוגי התראות נשלחים מוגדר בלשונית אילו התראות."],tip:"ל-WhatsApp אין דרך רשמית וחינמית לשלוח הודעה לעצמך. בוט בטלגרם או Webhook עושים אותו דבר."}
  ]},

  "set.sec":{title:"על הסיסמה והכניסה",lead:"מגנים על האפליקציה: הסיסמה, קוד נוסף מהטלפון, והמקומות שבהם אתה מחובר.",blocks:[
    {h:"בשביל מה הלשונית הזו",p:["באפליקציה הזו יש נתוני כסף פרטיים. ההגדרות האלה קובעות מי יכול לפתוח אותה."]},
    {h:"סיסמה",p:["הקלד את **הסיסמה הנוכחית** ו**סיסמה חדשה** באורך 10 תווים לפחות, ואז לחץ **שינוי סיסמה**.","שינוי הסיסמה מנתק כל מכשיר אחר."],ex:"השתמש במשפט ארוך שאפשר לזכור, לא במילה קצרה."},
    {h:"מפתח שחזור",p:["מפתח חד־פעמי שמאפשר לבחור סיסמה חדשה אם שוכחים אותה. הוא מוצג פעם אחת בלבד, מיד אחרי שהוא נוצר (גם כשבוחרים את הסיסמה בפעם הראשונה): לוחצים **העתקה**, **הורדה** או **הדפסה**, שומרים אותו במקום בטוח, לא במכשיר הזה, ולוחצים **שמרתי**.","אין עדיין מפתח? לוחצים **יצירת מפתח**. כדי להחליף אותו לוחצים **יצירת מפתח שחזור חדש**. אחר כך מקלידים את הסיסמה ולוחצים **יצירת מפתח**. המפתח הישן מפסיק לעבוד מיד."],tip:"כל מי שמחזיק במפתח יכול לבחור סיסמה חדשה, אז שמור עליו כמו על מפתח של הבית."},
    {h:"שכחת את הסיסמה",p:["במסך הכניסה לחץ **שכחתם את הסיסמה?**. אחר כך בחר **יש לי מפתח שחזור**, או **שליחת קוד לטלפון שלי** (מוצג רק כשההתראות מגיעות לטלפון שלך: הגדרות ← לאן נשלחות התראות). הקוד תקף 10 דקות.","בחר סיסמה חדשה. כשהכניסה הדו-שלבית פעילה, מתבקש גם הקוד מאפליקציית האימות. כל המכשירים מנותקים, והתראה מודיעה שהסיסמה שונתה.","אחרי שימוש במפתח השחזור מקבלים מפתח חדש: שמור גם אותו.","אף דרך לא עובדת? ב‑Docker הרץ **docker compose exec app node src/cli.js set-password**. באפליקציה ל‑Windows או ל‑Linux, התקן אותה מחדש ושחזר גיבוי."]},
    {h:"כניסה דו-שלבית",p:["זה מוסיף קוד בן 6 ספרות מהטלפון בכל כניסה, כך שסיסמה גנובה לא מספיקה.","לוחצים **הגדרה**. מופיעים קוד ריבועי לסריקה ומפתח להקלדה. סורקים את הקוד באפליקציית אימות (כמו Google Authenticator או Microsoft Authenticator), או מקלידים בה את המפתח. אחר כך מקלידים את הקוד בן 6 הספרות שהאפליקציה מראה ולוחצים **הפעלה**.","כדי לכבות, הקלד את הסיסמה ולחץ **כיבוי**."],tip:"שמור את המפתח במקום בטוח. אם תאבד גם את הטלפון וגם את המפתח, ייתכן שלא תוכל להיכנס."},
    {h:"הרגלים טובים",p:["השתמש בסיסמה שאתה לא משתמש בה בשום מקום אחר. הפעל כניסה דו-שלבית. לחץ **התנתקות מכל המכשירים** אם אי פעם איבדת מכשיר.","האפליקציה יכולה רק לקרוא את החשבונות שלך, אז גם מי שנכנס לא יכול להזיז את הכסף שלך. הוא עדיין יכול לראות את הנתונים שלך, ולכן ההגדרות האלה חשובות."]},
    {h:"מכשירים מחוברים",p:["נשארים מחוברים במכשיר 14 ימים.","כל מכשיר מחובר מופיע ברשימה, עם הפעם האחרונה שבה השתמשו בו. המכשיר שבו משתמשים עכשיו מסומן **זה המכשיר הזה**; לכל מכשיר אחר יש **התנתקות** כדי לנתק אותו.","תחת **המכשיר הזה**, **התנתקות** מנתקת רק את המכשיר הזה. **התנתקות מכל המכשירים** מנתקת את כל המכשירים, כולל זה."]},
    {h:"נעילת האפליקציה",p:["רק באפליקציית ה-Android: **לבקש ביטול נעילה כשהאפליקציה נפתחת** מבקש טביעת אצבע, זיהוי פנים או נעילת מסך. **לשאול שוב אחרי** קובע כמה זמן אפשר להיות מחוץ לאפליקציה לפני שהיא שואלת שוב."]}
  ]},

  "set.app":{title:"על גרסה ועדכונים",lead:"בודקים באיזו גרסה אתה, מעדכנים, ומתקינים את האפליקציה בטלפון או במחשב כמו אפליקציה רגילה.",blocks:[
    {h:"בשביל מה הלשונית הזו",p:["שלושה כרטיסים: **גרסה ועדכונים**, **התקנה במכשיר הזה**, ו**מכשירים אחרים** להתקנת האפליקציה במקומות נוספים."]},
    {h:"גרסה ועדכונים",p:["**הגרסה המותקנת** מראה מה אתה מריץ. **מה חדש** מפרט מה השתנה.","אפליקציית ה-Windows מתעדכנת לבד: היא מראה **הורדה ועדכון** ואז **הפעלה מחדש ועדכון**. יש גם **עדכון אוטומטי**: גרסאות חדשות מותקנות בפעם הבאה שתסגור את האפליקציה.","אם אתה מריץ את האפליקציה על השרת שלך, היא רק אומרת לך שיש גרסה חדשה יותר. כדי לעדכן, לוחצים Update (או Pull and redeploy) ב-Docker Desktop, ב-Portainer או ב-Dockhand, או מריצים בטרמינל את שתי הפקודות שמוצגות. הנתונים שלך נשמרים.","באפליקציית ה-Android, הכרטיס **האפליקציה הזאת** מראה את הגרסה של אפליקציית הטלפון. **פתיחת ההורדות** מביאה את החדשה ביותר מ-GitHub; השרת והנתונים לא נפגעים."],tip:"**בדיקת עדכונים** צריכה גישה לאינטרנט אל github.com."},
    {h:"התקנת האפליקציה",p:["התקנה פותחת את האפליקציה במסך מלא ממסך הבית ומאפשרת לה להיפתח בלי חיבור.","לוחצים **התקנת האפליקציה** אם הכפתור מוצג. אחרת **התקנה מהדפדפן** מראה את השלבים למכשיר הזה: ב-Chrome או ב-Edge במחשב, פותחים את תפריט הדפדפן ואז התקנת אפליקציה. ב-Android, פותחים את תפריט Chrome ואז הוספה למסך הבית. ב-iPhone, מקישים על שיתוף ואז הוספה למסך הבית.","השלבים למכשיר הזה מופיעים קודם. **מכשירים אחרים** מציג את השאר, עם האפליקציות שאפשר להוריד ל‑Windows, למק, ל‑Linux ול‑Android. לאייפון ולאייפד אין אפליקציה להורדה: מוסיפים אותה למסך הבית."]},
    {h:"מה חדש",p:["**מה חדש** ליד מספר הגרסה פותח רשימה קצרה של מה שהשתנה בכל גרסה, במילים פשוטות."]}
  ]},

  "set.log":{title:"על היסטוריית השינויים",lead:"יומן של כל מה ששונה באפליקציה: על ידך ועל ידי האפליקציה עצמה. משתמשים בו כדי לברר מה קרה, או כדי לבטל טעות.",blocks:[
    {h:"בשביל מה הלשונית הזו",p:["כל שינוי נרשם כאן, החדש ראשון: קטגוריה ששינית, תקציב, קופה, חשבון קבוע שנמצא, קופות שנשלם מהן אוטומטית, ועוד."]},
    {h:"איך קוראים שורה",p:["בכל שורה יש מה קרה, הפרטים, מי עשה (**אתה** או **מערכת**), והשעה."],ex:"עריכת קטגוריה - בית מרקחת: ללא קטגוריה ← בריאות - אתה - 3 באוקטובר, 14:02."},
    {h:"מה נרשם",p:["דברים שאתה עושה (הוספת עסקה, שינוי קטגוריה, עריכת קופה או תקציב) ודברים שהאפליקציה עושה לבד (מציאת חשבון קבוע, תשלום מקופה, החזרת תשלום לקופה).","שום דבר כאן לא משנה את הבנק האמיתי שלך. זה רק רישום בתוך האפליקציה."],ex:"**זוהה תשלום קבוע** - Netflix, חודשי, בערך ₪55 - מערכת."},
    {h:"ביטול",p:["בחלק מהשורות יש כפתור **ביטול הפעולה**. אפשר לבטל עריכות של קטגוריות, הערות, תקציבים וקופות. לוחצים והערך הישן חוזר."]},
    {h:"עוד שורות",p:["הרשימה מראה 50 בכל פעם. לחץ **עוד 50** כדי ללכת רחוק יותר."]}
  ]},

  appearance:{title:"על המראה",lead:"עושים שהאפליקציה תיראה איך שנוח לך. כל שינוי מוצג מיד ונשמר בדפדפן הזה בלבד, אז כל מכשיר יכול להיראות אחרת. **איפוס** (למעלה בצד) מחזיר את ברירות המחדל.",blocks:[
    {h:"מצב",p:["**מצב תצוגה**: **בהיר**, **כהה** או **לפי המכשיר**. לפי המכשיר עוקב אחרי ההגדרה של הטלפון או המחשב שלך."]},
    {h:"צבעים",p:["בוחרים **ערכת צבעים**. בוחרים **מותאם אישית** כדי ליצור ערכה משלכם: בוחרים צבע בסיס אחד והשאר מתאימים אליו, או קובעים כל צבע בנפרד. עורכים את הצבעים של המצב שבו אתם נמצאים (בהיר או כהה)."]},
    {h:"רקע",p:["**רקע**: עשרה סגנונות, מ**הילה** ו**שילוב** ועד **זוהר צפוני**, **אופק**, **דו־גוני**, **הילת פינות** ו**מניפה**, או **חלק** (בלי אפקט). **עוצמת המעבר** הופכת את הצבע לעדין או חזק יותר.","**מרקם** שם דוגמה קלה מעל: **ללא**, **נקודות**, **פסים**, **רשת** או **גרגירי**. **צפיפות המרקם** הופכת את הדוגמה לגדולה או קטנה יותר, ו**אטימות המרקם** הופכת אותה לחלשה או חזקה יותר."]},
    {h:"משטח",p:["**סגנון כרטיסים** קובע איך הכרטיסים נראים: **מלא**, **מסגרת**, **בולט** או **זכוכית**.","**זכוכית** מראה את הרקע מבעד לכל הכרטיסים, החלונות והתפריטים. מופיעים שלושה מחוונים: **טשטוש** (עד כמה הרקע מטושטש מבעדם), **עוצמת הצבעים** (עד כמה הוא בהיר וצבעוני) ו**אטימות** (עד כמה צבע הכרטיסים מלא: ב־100% הרקע מוסתר, ב־0% הוא נראה לגמרי). הרקע עצמו לא משתנה. אם האפליקציה איטית, חזרו ל**מלא**."]},
    {h:"פינות",p:["פינות **עגולות**, **רכות** או **חדות** בכרטיסים ובכפתורים."]},
    {h:"צפיפות ומרווחים",p:["אלה שני דברים שונים. **ריווח** (צפוף, רגיל, מרווח) משנה את המקום בתוך כרטיסים ושורות. **ריווח פריסה** (צפוף, רגיל, מאוורר, רחב) משנה את הרווח בין כרטיסים וקטעים.","במחשב, **ריווח בסרגל הצד** (צפוף, רגיל, מרווח) משנה את הרווח בין פריטי תפריט הצד."],ex:"ריווח צפוף עם ריווח פריסה רחב: כרטיסים קטנים שרחוקים זה מזה."},
    {h:"גופן וניווט",p:["**גופן**: **פשוט**, **קלאסי**, **מעוגל** או **מונו**.","במחשב, **סרגל צד** בוחר **עם שמות** (סמל ושם) או **אייקונים בלבד** (תפריט דק)."]},
    {h:"מראות שמורים",p:["**שמירה…** (ליד **איפוס**) שומרת את המראה הנוכחי בשם שבוחרים. הלשונית **נשמר** מציגה את **המראות שלכם**: **להשתמש** מחיל מראה, **בהיר** ו**כהה** בוחרים את המראה לכל מצב, **עדכון** מחליף אותו במראה הנוכחי, ו**×** מוחק אותו. מצב התצוגה ואייקון האפליקציה לא נשמרים במראה.","**אייקון האפליקציה** ו**שפה** נמצאים בהגדרות ← העדפות.","טיפ: לחץ על הלוגו בראש תפריט הצד כדי לקבל מראה חדש אקראי."]}
  ]},

  quick:{title:"על כפתור ה-+",lead:"כפתור ה-+ הוא דרך מהירה להוסיף או לעדכן דברים מכל עמוד. לוחצים עליו, בוחרים מה רוצים לעשות, וממלאים טופס קצר.",blocks:[
    {h:"בשביל מה כפתור ה-+",p:["לא צריך קודם למצוא את העמוד הנכון. במחשב זה כפתור ה-+ העגול בפינה התחתונה של המסך. בטלפון זה ה-+ בראש מסך הבית. החלון נקרא **הוספה ועדכון**."]},
    {h:"תנועה",p:["**תנועה** מוסיפה הכנסה או הוצאה ידנית. ממלאים **תיאור**, **סכום**, **סוג** (הוצאה או הכנסות), **תאריך**, **חשבון** (או מזומן) ו**קטגוריה**. **אוטומטי (לפי כללים)** נותן לכללי הקטגוריות לבחור. אפשר לצרף **קבלה (צלמו או בחרו קובץ)**.","אם החשבון הוא כזה שמנהלים ידנית, אפשר לסמן **לשנות גם את היתרה של החשבון הזה בסכום הזה**."],ex:"בית מרקחת, ₪48, הוצאה, היום, Max ·· 1234."},
    {h:"חשבון",p:["**חשבון** שואל איזה סוג חשבון זה: **בנק או כרטיס אשראי** (מחברים פעם אחת והאפליקציה קוראת אותו בשבילכם), או **חשבון שאני מנהל בעצמי** (מזומן, חיסכון במקום אחר, השקעה או הלוואה, עם יתרה שמזינים)."]},
    {h:"תמונת קבלה",p:["**תמונת קבלה** פותח את אותו טופס ופותח מיד את המצלמה או הקבצים שלך. מצלמים ומוסיפים את הפרטים. התמונה נשמרת עם העסקה."]},
    {h:"כלל קטגוריה וקטגוריה",p:["**כלל קטגוריה** יוצר כלל: כששם תנועה מכיל את הטקסט שלך, הוא מקבל את הקטגוריה שבחרת. הוא אף פעם לא משנה קטגוריה שקבעת ידנית.","**קטגוריה** יוצרת קטגוריה חדשה לפי שם."],ex:"אם התיאור מכיל “Wolt”, קטגוריה אוכל בחוץ."},
    {h:"תשלום קבוע, תקציב, קופה ויעד",p:["**תשלום קבוע** עוקב אחרי חיוב חוזר. **תקציב** קובע גבול חודשי לקטגוריה. **קופה** ו**יעד** פותחים שניהם את טופס הקופה החדשה: קופה היא כסף ששמים בצד, ויעד הוא קופה עם תאריך שעד אליו רוצים להגיע.","כל אחד פותח את אותו טופס כמו בעמוד שלו."]},
    {h:"פנסיה, ייבוא וסנכרון",p:["**יתרת הפנסיה** מעדכנת את הפנסיה ידנית. **ייבוא קובץ CSV** לוקח אותך להגדרות ← ייבוא וייצוא. **סנכרון עכשיו** קורא את כל החשבונות המחוברים."]}
  ]}
};

HELP["set.prof"]={title:"על הפרופיל",lead:"הפרופיל הוא כמה פרטים עליכם. כולם אופציונליים, ואף אחד מהם לא יוצא מהנתונים שלכם.",blocks:[
  {h:"למה משמש הפרופיל",p:["**השם** משמש לברכה בדף הבית. **הגיל** מאפשר להגדיר יעדים כמו סכום עד גיל מסוים. **המגדר** מאפשר לאפליקציה לדבר אליכם נכון בעברית, שבה המילים משתנות לנשים ולגברים.","לחצו **שמירה** כדי לשמור את השינויים. **ניקוי הפרופיל** מוחק הכול."],ex:"שם דנה, גיל 34, מגדר אישה: בדף הבית תראו **בוקר טוב, דנה**, ובעברית האפליקציה מדברת אליכן בלשון נקבה."},
  {h:"החלון של הפעם הראשונה",p:["בפעם הראשונה שפותחים את האפליקציה אחרי שהתווסף, חלון מציע את אותו טופס. **לא עכשיו** סוגר אותו לתמיד. אפשר למלא את הפרופיל כאן בכל זמן."]}
]};

HELP.recap={title:"על הסיכום",lead:"הסיכום מספר לכם במילים פשוטות איך החודש הנוכחי מתקדם. אין צורך לחפש כלום: הוא קורא את הנתונים וכותב את הסיפור.",blocks:[
  {h:"למה משמש הסיכום",p:["הוא עונה על שאלות שהייתם מחפשים בכמה דפים: מה נכנס, מה עוד צריך לשלם, כמה הוצאתם, אילו תקציבים בבעיה ולאן החודש הולך.","הוא אומר רק מה שנכון לכם עכשיו. משפט שלא רלוונטי פשוט לא מוצג."],ex:"**היי דנה, הנה אוקטובר שלכם עד עכשיו.** קיבלתם ₪18,900 ב‑9 באוקטובר. לפניכם עוד ₪6,200 של חשבונות ותשלומי כרטיס."},
  {h:"שורת הימים",p:["מתחת לשם שלכם החודש מוצג כשורה של פסים קטנים, אחד לכל יום. העבירו את העכבר על יום כדי לראות מה נכנס, מה הוצא ומה מתוכנן לו. לחצו על יום כדי לפתוח אותו בפעילות."]},
  {h:"השלבים",p:["הדף עוקב אחרי הכסף לפי הסדר: עם כמה **התחלתם** את החודש, מה **נכנס**, כמה **הוצאתם**, מה **נשאר** לכם היום, מה **עוד צריך לשלם**, מה **שווה לבדוק** (תקציב שעומד לחרוג, קופות שיחסר בהן, קטגוריה מעל הרגיל) ומה יהיה **כנראה בסוף החודש**.","כל שלב מראה את החשבון שמוביל ממספר אחד לבא, כך שרואים איך הגענו אליו. לחצו על כותרת של שלב כדי לפתוח את הדף עם כל הפרטים."]},
  {h:"כרטיסי אשראי",p:["קנייה בכרטיס אשראי נחשבת כהוצאה ביום שעשיתם אותה, גם אם הבנק משלם לחברת האשראי מאוחר יותר, ביום החיוב של הכרטיס. עד אז היא מופיעה כ**עוד לא ירד**, והיא חלק מ**עוד לשלם**.","כרטיס שמוריד את הכסף מיד, כמו כרטיס Wise, נחשב כמו כל תשלום מהחשבון. כשהחיוב של הכרטיס מופיע בבנק, הוא כבר לא נחשב כחוב. כל זה עובד לבד מתוך התנועות שלכם."]},
  {h:"מאיפה המספרים",p:["**התחלתם עם** הוא אומדן: היתרה של היום, פחות מה שנכנס החודש, ועוד מה שכבר יצא מהחשבונות.","**כנראה בסוף החודש** הוא מה שיש לכם היום פחות חיובי האשראי, התשלומים הקבועים שעוד צפויים ושאר ההוצאות הרגילות (התקציבים, או כמה שאתם בדרך כלל מוציאים כשאין תקציב). הוא מניח שלא תיכנס עוד הכנסה.","בימים האחרונים של החודש מופיעים גם התשלומים הקבועים שכנראה יגיעו בחודש הבא."],tip:"לחצו על כותרת של שלב כדי לעבור לדף עם כל הפרטים."}
]};
HELP["set.ai"]={title:"על המיון האוטומטי",lead:"האזורים האלה ממיינים את התשלומים בשבילך: נותנים להם קטגוריה, תגיות, שם ברור יותר, מסמנים חיובי כרטיס או אומרים מה כל כסף שנכנס. קטגוריה או שם שקבעת ידנית אף פעם לא משתנים.",blocks:[
  {h:"תנו לבינה מלאכותית ליצור לכם קטגוריות",p:["האפליקציה מגיעה רק עם הקטגוריות המעטות שהיא צריכה בעצמה. **תנו לבינה מלאכותית ליצור לכם קטגוריות** בונה את השאר מהתנועות שלך: מורידים את הקובץ עם שמות התנועות, מעתיקים את ההוראות לכל צ׳אט בינה מלאכותית ומצרפים את הקובץ, ואז מעלים את התשובה.","לפני שמשהו נוסף רואים מה בדיוק יתווסף, ואפשר לבטל סימון של קטגוריות שלא רוצים. שום דבר קיים לא משתנה, תנועות ששייכת בעצמך שומרות על הקטגוריה שלהן, והביטול עובד כרגיל.","בקובץ יש רק את השמות (חנויות ומשלמים), כמה פעמים כל אחד מופיע, והאם הכסף יצא או נכנס. אין בו סכומים, תאריכים או חשבונות. הוא כן נשלח לחברת הבינה המלאכותית שתבחר."]},
  {h:"כללי קטגוריות",p:["כלל אומר: אם שם התנועה מכיל את הטקסט הזה, השתמש בקטגוריה הזו. הכלל הראשון שמתאים מנצח. קטגוריה שקבעת ידנית אף פעם לא משתנה על ידי כלל.","כדי להוסיף אחד, הקלד את הטקסט, בחר קטגוריה ולחץ **הוספת כלל**. אפשר לערוך את הטקסט או הקטגוריה של כללים קיימים במקום, או ללחוץ **מחיקה**."],demo:"rule",ex:"אם התיאור מכיל “שופרסל”, הקטגוריה היא מכולת."},
  {h:"איפה כלל מחפש",p:["כל כלל נקרא כך: **אם** [איפה] [איך] [טקסט] ← [מה הוא עושה]. הרשימה הראשונה קובעת איפה לחפש: **הכול**, או חלק אחד של התנועה, כמו **שם התנועה**, **הערת הבנק** (טקסט נוסף מהבנק), **מי שילם**, **למי שולם**, **ההערה שלכם**, **החשבון שלכם**, **הקטגוריה של הבנק** או **המטבע ששולם בו** (כמו USD).","כל סוג כלל מתחיל במקומות שהוא תמיד קרא, למשל **שם, ממי או למי** בכללי קטגוריות. הרשימה השנייה קובעת איך משווים את הטקסט: **מכיל**, **זהה בדיוק**, **מתחיל ב**, **נגמר ב** או **לא מכיל**. הכללים שלך ממשיכים להתאים בדיוק למה שהתאימו קודם (עם **מכיל**), עד שמשנים את זה. השינוי נשמר בהיסטוריית השינויים ואפשר לבטל אותו."],ex:"אם הערת הבנק מכילה “acme ltd” ← משכורת."},
  {h:"כללי תגיות",p:["כלל תגית עובד כמו כלל קטגוריה, אבל הוא מוסיף תגית אחת או יותר. הוא מוסיף אותן מעבר לקטגוריה.","כשמוסיפים כלל, האפליקציה יכולה לתייג גם תשלומים שכבר יש לך. כלל צריך לפחות תגית אחת."],ex:"“netflix” מוסיף את התגית “סטרימינג”."},
  {h:"שמות תצוגה",p:["כלל שם תצוגה נותן לתנועות שם ברור יותר. רק מה שרואים משתנה: הטקסט של הבנק, הכללים והדוחות ממשיכים להשתמש במקור.","בוחרים איפה לחפש (**הכול**, **שם התנועה**, **הערת הבנק** וכו׳), **מכיל** או **זהה בדיוק**, את הטקסט ואת השם להצגה."],ex:"אם הערת הבנק מכילה “Acme Ltd” ← משכורת."},
  {h:"חיובי כרטיס",p:["שורת בנק שמכילה את הטקסט היא החיוב של כרטיס אשראי. היא לא נספרת כהוצאה, כי כל קנייה כבר נספרת בכרטיס.","חברות הכרטיסים הרגילות מזוהות בלי כלל."],ex:"“ישראכרט חיוב” ← חיוב כרטיס."},
  {h:"כסף שנכנס",p:["כסף שנכנס שמופיע בו הטקסט (בשם התנועה, בשם המשלם או בהערת הבנק) הוא מה שבוחרים: **משכורת** או **החזר כספי**. הבחירה שלכם בתשלום עצמו קודמת.","בלי כלל: כסף שנכנס לכרטיס אשראי הוא החזר כספי, וכל כסף אחר שנכנס הוא הכנסה. שום דבר לא נקבע לפי מילים בטקסט.","כלל לא משנה קטגוריה: משכורת והחזר כספי הם לא קטגוריות."],ex:"“wix” ← משכורת. “insurer” ← החזר כספי."}
]};
for (const k of ["crules", "trules", "nrules", "cprules", "srules"]) HELP["set." + k] = HELP["set.ai"];
